-- 600 genuine Australian job postings, captured 2026-09-19.
-- 200 each: AI engineering, finance analysis/reporting, accounting/bookkeeping/audit.
-- Freehire API: https://freehire.me/docs/api ; Adzuna API: https://developer.adzuna.com/docs/search
-- Adzuna and WhatJobs supply JD excerpts only; description_is_excerpt flags these.
-- source_url points to the source posting. Do not treat older ads as guaranteed open.
begin;

alter table public.jobs add column if not exists source_board text;
alter table public.jobs add column if not exists source_external_id text;
alter table public.jobs add column if not exists source_url text;
alter table public.jobs add column if not exists source_posted_at timestamptz;
alter table public.jobs add column if not exists description_is_excerpt boolean not null default false;
alter table public.jobs add column if not exists source_group text;
create unique index if not exists jobs_source_identity_idx
  on public.jobs (source_board, source_external_id)
  where source_board is not null and source_external_id is not null;

on conflict (id) do nothing;

with source_rows as (
  select * from jsonb_to_recordset($jade_real_jobs$[{"id":"e6e9aff0-8919-57cb-9eff-7bfb9697abe7","company_id":"b7b44df3-7d51-5394-ac6d-0e6acd399e63","title":"VIE AI Engineer Consultant","location":"Sydney, NSW, au","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"junior","description":"Within the AI & Data Business Unit, you will help organizations transform their business processes through Generative and Agentic AI. Working alongside Data Scientists, Machine Learning Engineers, Solution Architects, and Platform Engineers, and working step-by-step with customers, you will design, build, and deploy enterprise-grade AI systems that create measurable business value. Your key responsibilities include: \n\n• \nAssist the GenAI Solution Architect in designing scalable and secure AI solutions. \n\n• \nDevelop applications powered by foundation models, both self-managed and API-accessible, that meet business needs and comply with applicable regulations (GDPR, EU AI Act, model licenses, etc.). \n\n• \nDesign prompting and orchestration strategies to improve reasoning, controllability, reliability, and user experience. \n\n• \nDesign and optimize Retrieval-Augmented Generation (RAG) systems leveraging enterprise knowledge sources, semantic search, and source attribution. \n\n• \nDesign, implement, and optimize agentic AI systems using orchestration frameworks such as LangGraph, CrewAI, AutoGen, Semantic Kernel, or equivalent. \n\n• \nDevelop AI agents capable of tool usage, workflow orchestration, planning, reasoning, memory management, and human-in-the-loop interactions. \n\n• \nArchitect AI solutions integrating enterprise systems, APIs, databases, and knowledge repositories. \n\n• \nEvaluate and select the most appropriate models based on business requirements, performance, latency, and cost constraints. \n\n• \nMonitor AI system performance in production and contribute to observability, evaluation, and governance practices. \n\n• \nConduct research on the latest advances in foundation models, multimodal AI, and agentic AI systems. \nYou hold a Master’s degree from an engineering school or an advanced degree in computer science, engineering, or artificial intelligence and you have at least one year of technical experience building creative AI solutions. \nYou are proficient in Python programming and code versioning, and ideally have experience with Generative AI frameworks (LangChain, LangGraph, RAG), advanced prompting techniques, and are familiar with Open-Source AI ecosystems (Antropic, OpenAI) as well as cloud-native architectures and modern AI deployment practices. \nYou want to get involved and quickly take on responsibility for high-value-added assignments within a dynamic organization. You are passionate about pushing the boundaries of AI technology and making a significant impact in enabling our customers to create GenAI-powered applications with confidence and a fast time to market. \nFinally, are you curious and enjoy working as part of a team? Do you want to join a dynamic and motivating professional environment? Do you share our values of excellence, entrepreneurship, innovation, sharing, kindness, and work-life balance? \nAre you fluent in English? \nThen join us! \nPlease send us your CV in English. \nPlease ensure you meet the VIE contract eligibility criteria as established by Business France:\n\n• Anyone over 18 and under 28 years of age on the date of registration may apply for an International Volunteer Program (VIE).\n• Departure on assignment must take place no later than the day of your 29th birthday. Beyond this, no exceptions are granted.\n• You must hold French or European nationality (a national of a Member State of the European Economic Area, which comprises the 28 Member States of the European Union, Norway, Iceland, and Liechtenstein) or Monégasque nationality.\n• You must be in compliance with the national service obligations of the country of which you are a national.\n• You must be in possession of your civic rights and have a clean criminal record.\n\nSia is an equal opportunity employer. All aspects of employment, including hiring, promotion, remuneration, or discipline, are based solely on performance, competence, conduct, or business needs.","source_board":"freehire:smartrecruiters","source_external_id":"vie-ai-engineer-consultant-sia-n5cg6lww","source_url":"https://jobs.smartrecruiters.com/Sia/744000150370520-vie-ai-engineer-consultant-","source_posted_at":"2026-09-18T13:14:17Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"26ffd8cf-3991-5b9f-a418-c83aa8326ff6","company_id":"e81c8cc1-3761-59bd-a9bf-e4258ee627ef","title":"Python Developer - AI/ML","location":"Clayton, Melbourne VIC","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"About the role\nWe are seeking an experienced Python Developer for an opportunity working with the AiLECS Lab, a collaboration between Monash University and the Australian Federal Police. The role will focus on developing and optimising AI/ML models and applications, working with large datasets and collaborating with data scientists, engineers and research fellows to take machine learning projects from development through to production.\n\nKey responsibilities\n\n• \nDevelop and optimise machine learning models and applications using Python\n• \nBuild and fine-tune ML models using frameworks such as PyTorch, TensorFlow, Hugging Face and Ultralytics\n• \nImplement machine learning algorithms from research papers into robust and scalable software\n• \nEvaluate and benchmark model performance using appropriate metrics\n• \nClean, prepare and augment large datasets for model development\n• \nDevelop APIs and integrate AI systems with existing applications and platforms\n• \nApply MLOps practices to support model development, evaluation and deployment\n• \nWork within Agile development environments using tools such as GitLab, GitHub or Azure DevOps\n\nAbout you\n\n• \nMinimum 2 years' experience in Python software development\n• \nExperience developing and/or fine-tuning machine learning models\n• \nStrong understanding of machine learning algorithms and AI model architectures\n• \nExperience with PyTorch and/or TensorFlow\n• \nExperience with libraries such as NumPy, Hugging Face and/or Ultralytics\n• \nExperience evaluating and benchmarking ML model performance\n• \nExperience developing REST APIs and integrating applications\n• \nFamiliarity with CI/CD, version control and software testing\n• \nExperience working with Agile methodologies\n• \nAustralian Citizens with an ability to obtain NV1","source_board":"freehire:seek","source_external_id":"python-developer-ai-ml-appsytec-6ydv3tvv","source_url":"https://www.seek.com.au/job/94712347","source_posted_at":"2026-09-17T23:39:20Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"0fd32c19-ae81-53e7-a052-ce4ad440f8b7","company_id":"af116472-589c-51ec-9b37-af5f557be5cf","title":"Systems Engineer - AI Safety and Tooling","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"The Development Platform organization at IMC Trading is focused on accelerating tech team workflows by providing self-service tools, services, documentation, and support. We design, build, and maintain the platforms that IMC's software development lifecycle depends on, establishing a consistent technical foundation across regions and empowering teams to innovate efficiently.\n\nIMC is embedding agentic AI directly into the developer workflow for our production-critical systems. The Development Platform team operates the infrastructure that makes this possible: the environments where AI agents run, the integrations that connect them to our systems, and the safety and security controls that keep them reliable and auditable.\n\nWe are seeking a versatile Systems Engineer to build and operate the infrastructure behind IMC's AI-powered engineering initiative. You will integrate AI SaaS offerings, run the containerization and virtualization layers that AI agents depend on, and harden the security of agents and the internal services they interact with. As AI adoption across our tech teams grows, so does the need for robust, secure, and observable infrastructure around it.\n\nBased in Sydney, you will be the local point of contact for our global AI platform and infrastructure teams, collaborating closely with them while supporting the development teams who consume these capabilities every day.\n\nYour Core Responsibilities: \n\n• Integrate, deploy, and operate AI SaaS offerings and self-hosted AI services, collaborating cross-functionally to deliver new tools and capabilities to our tech teams.\n\n• Design and maintain the containerization and virtualization environments in which AI agents, MCP servers, and supporting services run, ensuring they are isolated, reproducible, and scalable.\n\n• Drive security hardening of AI agents and the internal services exposed to them: secrets management, access controls, sandboxing, network policy, and auditability of agent actions.\n\n• Write and maintain code to extend, integrate, and automate the services we support, from API integrations to internal tooling and automation frameworks.\n\n• Build the telemetry, monitoring, and evaluation infrastructure needed to make AI-driven workflows reliable, observable, and safe to run against production-critical systems.\n\n• Partner with development teams to align platform capabilities with their evolving AI workflows, and act as the regional point of contact for global AI platform and infrastructure collaboration.\n\n• Diagnose and resolve incidents swiftly, working with regional peers in a 'follow the sun' model to guarantee continuous system availability.\n\nYour Skills and Experience: \n\n• 3+ years of work experience in a relevant role\n\n• Bachelor's Degree in Computer Engineering, Computer Science or equivalent\n\n• Strong programming experience in Python or Go; Shell scripting is a plus.\n\n• Strong knowledge of Linux/Unix Systems\n\n• Hands-on experience with containerization and virtualization technologies, including Kubernetes and Docker.\n\n• Experience integrating and operating third-party SaaS solutions, both on-premises and leveraging AWS cloud services.\n\n• Understanding of security principles and best practices, including secrets management, sandboxing, and compliance frameworks.\n\n• Experience designing disaster recovery plans, high availability (HA) configurations, and failover strategies.\n\n• Experience with CI/CD tools such as Jenkins, GitLab CI, or TeamCity, including the automation of build, test, and deployment processes.\n\n• Curiosity and eagerness to learn about AI/LLM application patterns, even if you haven't worked closely with them yet; exposure to agentic AI tools and workflows (e.g., coding agents, MCP servers) or model-serving and evaluation infrastructure is a plus.\n\nAbout Us\n\nIMC is a research-driven trading firm where quantitative modeling, machine learning, and engineering shape how modern markets are traded. A stabilizing force in markets since 1989, we provide liquidity across trading venues, delivering the best outcome in value and risk management to investors. Using our own technology and capital, we build proprietary systems and algorithms that operate across global markets. Our researchers, traders, and engineers work as a collective, combining rapid experimentation, advanced infrastructure, and real-time feedback to turn insight into execution and execution into advantage.","source_board":"freehire:greenhouse","source_external_id":"systems-engineer-ai-safety-and-tooling-imc-trading-xxbwy4tz","source_url":"https://job-boards.eu.greenhouse.io/imc/jobs/4918139101","source_posted_at":"2026-09-15T15:21:55Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"91ab9d86-a658-5243-b8e7-399aef681cc8","company_id":"af116472-589c-51ec-9b37-af5f557be5cf","title":"Python Engineer - AI","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"Our Sydney Business Operations Engineering team creates scalable, business-critical applications and tools that automate and support teams across IMC. They gather requirements and feedback from a wide range of internal stakeholders and turn them into creative automation solutions built on modern engineering practices.\n\nAs the team grows the number of processes it runs and the range of stakeholders it supports, we are investing heavily in how we scale by using agentic coding to accelerate development, and building AI into the automation itself so that analysis which has always been manual can start with a machine-generated first pass. You would join a small team with real ownership and a direct line to the people who use what you build.\n\nYour core responsibilities:\n\n• Develop, test, deploy, and maintain high-performance Python applications.\n\n• Build agentic workflows that perform first-pass analysis, so our business teams start from a considered position rather than a blank page\n\n• Design agents that work through a problem end to end — assembling the relevant data, identifying likely causes, and presenting something a subject-matter expert can interrogate\n\n• Take ownership of end-to-end development, from requirements gathering through to production deployment\n\n• Use agentic coding tools to move faster, while holding a high bar for what goes into production\n\n• Apply strong automated testing practices and frequent deployment to deliver incremental value \n\n• Balance trade-offs between latency, throughput, simplicity, scalability, and maintainability in a complex technology landscape.\n\nYour skills and experience:\n\n• 3+ years of professional software engineering experience, with a strong focus on Python\n\n• You have shipped something real with LLMs or agentic tooling — an agent, a workflow, an internal tool — and can talk about where it worked, where it did not, and what you would do differently\n\n• Experience with automated testing and CI/CD pipelines Strong communication skills and the ability to work with cross-functional teams and non-technical stakeholders\n\n• Prior knowledge of financial markets or trading is not required, but curiosity and a willingness to learn are essential\n\nAbout Us\n\nIMC is a research-driven trading firm where quantitative modeling, machine learning, and engineering shape how modern markets are traded. A stabilizing force in markets since 1989, we provide liquidity across trading venues, delivering the best outcome in value and risk management to investors. Using our own technology and capital, we build proprietary systems and algorithms that operate across global markets. Our researchers, traders, and engineers work as a collective, combining rapid experimentation, advanced infrastructure, and real-time feedback to turn insight into execution and execution into advantage.","source_board":"freehire:greenhouse","source_external_id":"python-engineer-ai-imc-trading-c3jb76az","source_url":"https://job-boards.eu.greenhouse.io/imc/jobs/4955625101","source_posted_at":"2026-09-15T15:21:55Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"e8fcb482-ef60-51b1-8a1d-7ec5a9d1cc8d","company_id":"42610294-daaf-5999-af8e-596d5689ff53","title":"AI Engineer - Agentic Engineering","location":"Melbourne VIC","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"Salary: $190000.00 - $210000.00 p.a. + Bonus\n\nKnowledge: \n\n• ​​Strong knowledge of software engineering techniques and development processes and tools, for example, IDEs, SCCS, Algorithms and Data Structures, Automated testing and computer system and cloud operations​ \n\n• Advanced proficiency with Python; working familiarity with ML frameworks such as TensorFlow or PyTorch \n\n• Strong knowledge of current AI/ML technologies and their applications \n\n• Team leadership and team dynamics \n\n• Strong knowledge of agentic AI engineering - designing, building and orchestrating AI agents, including agent frameworks, tool/function calling, multi-agent workflows, MCP (Model Context Protocol) servers and reusable agent skills \n\n• Familiarity with modern AI-assisted engineering tools (e.g. Claude Code, Codex, Kiro, agent loops and automations) \n\n• Understanding of designing and operating agent platforms on cloud (AWS preferrably), including containerisation (Docker/Kubernetes), MLOps/LLMOps and CI/CD \n\n• Understanding of responsible AI, AI safety and governance - guardrails, security, data privacy, and evaluation/testing of LLM and agent applications (e.g. A/B and back-to-back testing, ModelOps/LLMOps) \nExperience: \n\n• ​​Minimum of 2 years' experience in a relevant AI, machine learning or software engineering role covering solution development, implementation and deployment, with extensive commercial development in Python (or similar languages)​ \n\n• Demonstrated experience with cloud technology (e.g. AWS, Azure or similar) and in analysing and organising structured and unstructured data \n\n• Strong communication and stakeholder management skills \n\n• Extensive experience in analysing and developing software applications to deliver business solutions \n\n• Demonstrated experience building AI agents, MCP (Model Context Protocol) servers and reusable skills for specific business use cases, using modern AI-assisted development tools (e.g. Claude Code, Codex, Kiro, agent loops and automations) \n\n• Experience designing and building agent / AI platforms on cloud, delivering scalability, cost efficiency, safety, security and the evaluation/testing of agent and LLM applications \n\n• Demonstrated experience in applied AI engineering, machine learning and data science, including working with language models, RAG, vector databases and knowledge graphs \n\n• Experience working in and leading software engineering teams across a full-stack development environment \n\n• Experience in the electricity industry desirable","source_board":"freehire:seek","source_external_id":"ai-engineer-agentic-engineering-emmbr-kyvyubtc","source_url":"https://www.seek.com.au/job/94421220","source_posted_at":"2026-09-04T06:32:13Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"9857162a-22d5-5459-9661-3056892ba3f0","company_id":"f40e87a4-61f9-5390-806e-6a33f9bb3899","title":"Android Software Engineer - AI Neobank App","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"About Doit\nWe are focused on reinventing how people spend, save, invest, exchange, travel, and more. Our objective is to build tools that will help people get more from their money and become an expert at ease. We believe AI will help make finance smart, assessible and safe. \n\nWe are looking for the most talented and driven people we can find. We are looking for people who work for their passion, not counting hours. Who loves building great next-generation products, not status quo. Who cares about redefining how everyone around us can get the best financial applications, not for an exclusive few. We have teams working around the world, with over 20 nationalities and growing from our offices and remotely. Join us and build a better future for our society. \n\nIn 2019, we built the first mobile-first, insurance platform, enabling insurance to be accessible online by millions in the region. Today, it's the leading insurance platform in Southeast Asia.\n\nThe Role\nWe are looking for Android software engineers to build the native Android experience for Doit's AI Neobank App.\n\nThis role is for someone who cares about clean user flows, fast performance, product quality and shipping reliable mobile features used by real customers.\n\nWhat You'll Own\n\n• \nBuild and ship Android features using Kotlin.\n• \nCreate clean mobile flows for insurance, payments, claims, renewals and financial services.\n• \nWork with product and design to simplify complex user journeys.\n• \nIntegrate backend APIs and ensure mobile flows are stable, secure and reliable.\n• \nImprove app performance, crash rate, loading states, responsiveness and memory usage.\n• \nUse analytics, user behaviour and production issues to improve the product.\n• \nBuild AI-assisted mobile experiences only where they genuinely improve the user journey.\n\nWhat We're Looking For\n\n• \n3+ years of Android development experience using Kotlin.\n• \nStrong Android fundamentals and experience shipping production apps.\n• \nGood knowledge of Jetpack, Coroutines, Flow and modern Android architecture.\n• \nStrong sense of mobile UX, usability, edge cases and user flows.\n• \nExperience integrating REST APIs and debugging production issues.\n• \nFast execution, high ownership and strong attention to product quality.\n• \nApp links, GitHub, screenshots or examples of shipped work are a strong advantage.\n\nTech Stack\n\n• \nKotlin\n• \nJetpack Compose\n• \nAndroid SDK\n• \nCoroutines & Flow\n• \nSQL / NoSQL\n• \nTensorFlow Lite (on-device inference)\n\nThe Kind of Builder We Want\n\n• \nThinks in user journeys, not just screens.\n• \nCares about making complex financial products feel simple.\n• \nMoves fast without creating messy code.\n• \nNotices UX, performance and reliability issues before users complain.\n• \nHonest about what they personally built, what was team-owned and what impact they can or cannot claim.\n\nThis Role Is Not For\n\n• \nEngineers who only want fully defined tickets.\n• \nDevelopers who build screens without caring about user experience.\n• \nPeople who ignore crashes, edge cases, loading states or performance.\n• \nEngineers who move slowly in a startup environment.\n• \nPeople who exaggerate impact without explaining their actual contribution.\n\nLocation\nThis role is remote, but candidates must be based in Australia. We are hiring specifically for this market, so applicants should already be based in Australia.\n\nLanguage\nEnglish is our main working language across global teams. Strong English communication is required.\n\nInterview Process\nOur process is designed to move fast:\n1. Online assessment or practical task\n2. Role-specific interview\n3. CEO / final round\n\nFor strong candidates, we aim to complete the process and make an offer within 1 week from the start of the interview process. Candidates who complete assessments quickly will be prioritized.","source_board":"freehire:ashby","source_external_id":"android-software-engineer-ai-neobank-app-bjakcareer-7zix5w3s","source_url":"https://jobs.ashbyhq.com/bjakcareer/9f9caf73-0443-4e9b-ac4f-4fe33110dbe6","source_posted_at":"2026-09-01T04:00:54Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"0b56eb5c-95d3-575f-b000-d4995d204111","company_id":"f40e87a4-61f9-5390-806e-6a33f9bb3899","title":"Android Developer - AI Finance Agent","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"About Doit\nWe are focused on reinventing how people spend, save, invest, exchange, travel, and more. Our objective is to build tools that will help people get more from their money and become an expert at ease. We believe AI will help make finance smart, assessible and safe. \n\nWe are looking for the most talented and driven people we can find. We are looking for people who work for their passion, not counting hours. Who loves building great next-generation products, not status quo. Who cares about redefining how everyone around us can get the best financial applications, not for an exclusive few. We have teams working around the world, with over 20 nationalities and growing from our offices and remotely. Join us and build a better future for our society. \n\nIn 2019, we built the first mobile-first, insurance platform, enabling insurance to be accessible online by millions in the region. Today, it's the leading insurance platform in Southeast Asia.\n\nThe Role\nWe are looking for Android software engineers to build the native Android experience for Doit's AI Finance Agent.\n\nThis role is for someone who cares about clean user flows, fast performance, product quality and shipping reliable mobile features used by real customers.\n\nWhat You'll Own\n\n• \nBuild and ship Android features using Kotlin.\n• \nCreate clean mobile flows for insurance, payments, claims, renewals and financial services.\n• \nWork with product and design to simplify complex user journeys.\n• \nIntegrate backend APIs and ensure mobile flows are stable, secure and reliable.\n• \nImprove app performance, crash rate, loading states, responsiveness and memory usage.\n• \nUse analytics, user behaviour and production issues to improve the product.\n• \nBuild AI-assisted mobile experiences only where they genuinely improve the user journey.\n\nWhat We're Looking For\n\n• \n3+ years of Android development experience using Kotlin.\n• \nStrong Android fundamentals and experience shipping production apps.\n• \nGood knowledge of Jetpack, Coroutines, Flow and modern Android architecture.\n• \nStrong sense of mobile UX, usability, edge cases and user flows.\n• \nExperience integrating REST APIs and debugging production issues.\n• \nFast execution, high ownership and strong attention to product quality.\n• \nApp links, GitHub, screenshots or examples of shipped work are a strong advantage.\n\nTech Stack\n\n• \nKotlin\n• \nJetpack Compose\n• \nAndroid SDK\n• \nCoroutines & Flow\n• \nSQL / NoSQL\n• \nTensorFlow Lite (on-device inference)\n\nThe Kind of Builder We Want\n\n• \nThinks in user journeys, not just screens.\n• \nCares about making complex financial products feel simple.\n• \nMoves fast without creating messy code.\n• \nNotices UX, performance and reliability issues before users complain.\n• \nHonest about what they personally built, what was team-owned and what impact they can or cannot claim.\n\nThis Role Is Not For\n\n• \nEngineers who only want fully defined tickets.\n• \nDevelopers who build screens without caring about user experience.\n• \nPeople who ignore crashes, edge cases, loading states or performance.\n• \nEngineers who move slowly in a startup environment.\n• \nPeople who exaggerate impact without explaining their actual contribution.\n\nLocation\nThis role is remote, but candidates must be based in Australia. We are hiring specifically for this market, so applicants should already be based in Australia.\n\nLanguage\nEnglish is our main working language across global teams. Strong English communication is required.\n\nInterview Process\nOur process is designed to move fast:\n1. Online assessment or practical task\n2. Role-specific interview\n3. CEO / final round\n\nFor strong candidates, we aim to complete the process and make an offer within 1 week from the start of the interview process. Candidates who complete assessments quickly will be prioritized.","source_board":"freehire:ashby","source_external_id":"android-developer-ai-finance-agent-bjakcareer-y6gkwpfi","source_url":"https://jobs.ashbyhq.com/bjakcareer/bc9b7692-5054-480b-81a2-680ffca3252f","source_posted_at":"2026-09-01T04:01:07Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"237f2ee3-a6a6-5257-85f7-f3de846cff72","company_id":"f40e87a4-61f9-5390-806e-6a33f9bb3899","title":"Mobile Application Developer - AI Neobank App","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"About Doit\nWe are focused on reinventing how people spend, save, invest, exchange, travel, and more. Our objective is to build tools that will help people get more from their money and become an expert at ease. We believe AI will help make finance smart, assessible and safe. \n\nWe are looking for the most talented and driven people we can find. We are looking for people who work for their passion, not counting hours. Who loves building great next-generation products, not status quo. Who cares about redefining how everyone around us can get the best financial applications, not for an exclusive few. We have teams working around the world, with over 20 nationalities and growing from our offices and remotely. Join us and build a better future for our society. \n\nIn 2019, we built the first mobile-first, insurance platform, enabling insurance to be accessible online by millions in the region. Today, it's the leading insurance platform in Southeast Asia.\n\nThe Role\nWe are looking for Android engineers to build the native Android experience for Doit's AI Neobank App.\n\nThis role is for someone who cares about clean user flows, fast performance, product quality and shipping reliable mobile features used by real customers.\n\nWhat You'll Own\n\n• \nBuild and ship Android features using Kotlin.\n• \nCreate clean mobile flows for insurance, payments, claims, renewals and financial services.\n• \nWork with product and design to simplify complex user journeys.\n• \nIntegrate backend APIs and ensure mobile flows are stable, secure and reliable.\n• \nImprove app performance, crash rate, loading states, responsiveness and memory usage.\n• \nUse analytics, user behaviour and production issues to improve the product.\n• \nBuild AI-assisted mobile experiences only where they genuinely improve the user journey.\n\nWhat We're Looking For\n\n• \n3+ years of Android development experience using Kotlin.\n• \nStrong Android fundamentals and experience shipping production apps.\n• \nGood knowledge of Jetpack, Coroutines, Flow and modern Android architecture.\n• \nStrong sense of mobile UX, usability, edge cases and user flows.\n• \nExperience integrating REST APIs and debugging production issues.\n• \nFast execution, high ownership and strong attention to product quality.\n• \nApp links, GitHub, screenshots or examples of shipped work are a strong advantage.\n\nTech Stack\n\n• \nKotlin\n• \nJetpack Compose\n• \nAndroid SDK\n• \nCoroutines & Flow\n• \nSQL / NoSQL\n• \nTensorFlow Lite (on-device inference)\n\nThe Kind of Builder We Want\n\n• \nThinks in user journeys, not just screens.\n• \nCares about making complex financial products feel simple.\n• \nMoves fast without creating messy code.\n• \nNotices UX, performance and reliability issues before users complain.\n• \nHonest about what they personally built, what was team-owned and what impact they can or cannot claim.\n\nThis Role Is Not For\n\n• \nEngineers who only want fully defined tickets.\n• \nDevelopers who build screens without caring about user experience.\n• \nPeople who ignore crashes, edge cases, loading states or performance.\n• \nEngineers who move slowly in a startup environment.\n• \nPeople who exaggerate impact without explaining their actual contribution.\n\nLocation\nThis role is remote, but candidates must be based in Australia. We are hiring specifically for this market, so applicants should already be based in Australia.\n\nLanguage\nEnglish is our main working language across global teams. Strong English communication is required.\n\nInterview Process\nOur process is designed to move fast:\n\n• \nOnline assessment or practical task\n• \nRole-specific interview\n• \nCEO / final round\n\nFor strong candidates, we aim to complete the process and make an offer within 1 week from the start of the interview process. Candidates who complete assessments quickly will be prioritized.","source_board":"freehire:ashby","source_external_id":"mobile-application-developer-ai-neobank-app-bjakcareer-uto76e5w","source_url":"https://jobs.ashbyhq.com/bjakcareer/489ecf14-84bf-404d-9554-52b9367a787f","source_posted_at":"2026-09-01T04:00:58Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"f7ae2352-f39b-5201-8b71-9bf35fcc3628","company_id":"a7a4e2f3-8820-5d8e-9447-6cb973ee5cff","title":"Software/AI Engineer - Graduate Opportunity","location":"Geelong, South West Coast VIC","job_type":"graduate","industry":"AI & Software","career_id":"ml-engineer","experience_level":"entry-level title","description":"About the role\nHelp build the future of Building Inspections. You'll work directly with experienced building inspectors to develop AI that reads plans, understands regulations, matches site photos to designs and helps produce accurate reports.\nKey responsibilities\n\n• \nDevelop AI that reads plans and understands regulations\n• \nCreate systems that match site photos to designs\n• \nHelp produce accurate reports\nAbout you\n\n• \nFinal year or recently graduated AI or software engineer\n• \nCuriosity, creativity and problem-solving skills\n• \nExperience building side projects or teaching yourself new tech\nBenefits\n\n• \nReal salary\n• \nMentorship from industry veterans\n• \nChance to help build a platform from day one","source_board":"freehire:seek","source_external_id":"software-ai-engineer-graduate-opportunity-ggbi-registered-building-inspectors-vfo46f7c","source_url":"https://www.seek.com.au/job/94181849","source_posted_at":"2026-08-25T02:12:03Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"92ea6ffc-7333-5de6-9d58-d0e6b49b3214","company_id":"96ea3435-bc12-5207-b60f-6ac0ab30efa7","title":"Founding ML Engineer","location":"Melbourne","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"About Us\nBase Compute is an AI inference lab. Our mission is to bring AGI on device. We believe in a world where everyone has access to intelligence: fast, private and always available on your device.\nWe’re building the infrastructure for the next generation of on-device AI, from silicon-level optimizations to distributed inference systems.\nWe’re working on hard problems at the intersection of inference efficiency, model intelligence and autonomous research.\n\nThe Role\nWe’re looking for a Founding ML Engineer to work at the frontier of on-device AI. This role is for someone who lives at the intersection of systems engineering and machine learning, turning state-of-the-art research into hyper-optimized, production-ready infrastructure.\nYou’ll have significant ownership over our entire inference stack and direct influence on the technical bets the company makes.\n\nWhat You’ll Work On\n\n• \nInference engine development: Building and scaling our custom inference engine, handling everything from weight loading and KV-cache management to efficient request scheduling\n• \nCross-platform silicon optimization: Writing and tuning custom kernels and leveraging hardware-specific instructions to squeeze maximum performance out of diverse architectures, including Apple Silicon, NVIDIA, AMD, Snapdragon, and other edge platforms\n• \nSystems architecture: Developing robust, low-latency serving runtimes in C++ to manage model routing, continuous batching, and novel decoding strategies under strict thermal and memory constraints\n• \nPerformance profiling: Identifying and eliminating bottlenecks across the entire stack, from memory bandwidth ceilings to kernel interleaving\n\nWhat We’re Looking For\n\n• \n3+ years of experience in ML engineering or systems programming (Rust, C/C++), with a strong track record of building performance-critical software\n• \nExpertise in GPU programming and hardware optimization across various platforms (CUDA, ROCm, Metal, Triton, or similar)\n• \nSolid understanding of modern LLM architectures, including parsing formats and implementing optimization techniques (quantization, speculative decoding, etc.)\n• \nA strong sense of ownership and autonomy: the ability to take ambiguous architectural challenges and drive them from research translation directly into production-ready infrastructure\n• \nGood communication: the ability to explain complex architectural decisions simply, give honest feedback and document systems cleanly\n• \nNice-to-haves:\n\n• \nFamiliarity with ML compilers (torch.compile, custom operators)\n• \nExperience with low-precision inference (INT8/FP8/FP4)\n• \nKnowledge of Edge LLMOps\n\nWhat We Offer\n\n• \nFounding team equity and strong base salary\n• \nDirect influence on technical direction: your ideas will shape the roadmap\n• \nWork on genuinely hard problems that haven't been solved yet\n• \nSmall team, fast iteration, low bureaucracy\n\nLocation\nThe team is based in Melbourne and Berlin and works in-person from the office most days. We require strong written and spoken English, since the team collaborates across time zones.","source_board":"freehire:ashby","source_external_id":"founding-ml-engineer-base-compute-e25xob25","source_url":"https://jobs.ashbyhq.com/basecompute/61940c5a-b3bb-4bd2-9869-8d8b4de991c9","source_posted_at":"2026-07-03T06:09:50Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"042fa77d-bafe-5244-a036-875eb8bee83e","company_id":"36362900-4085-56b9-87c6-963d79e34a25","title":"Applied AI Engineer – Student or Graduate","location":"The Rocks, Sydney","job_type":"graduate","industry":"AI & Software","career_id":"ml-engineer","experience_level":"entry-level title","description":"JD excerpt from adzuna; read the complete posting at https://www.adzuna.com.au/land/ad/5880666751?se=wJr_gPCz8RGjHJHOFkzdXQ&v=6A1B95B63DCAA008C8E09BF3CE2B509D01095695\n\nThis is a Applied AI Engineer – Student or Graduate role with Deloitte based in Sydney, NSW, AU Deloitte Role Seniority - intern, graduate More about the Applied AI Engineer – Student or Graduate role at Deloitte Applied AI Researcher / Engineer – Student or Graduate About the opportunity We are looking for a university student or recent graduate who is interested in applying artificial intelligence to real-world business problems. You will work alongside an experienced team to help explore, …","source_board":"adzuna","source_external_id":"5880666751","source_url":"https://www.adzuna.com.au/land/ad/5880666751?se=wJr_gPCz8RGjHJHOFkzdXQ&v=6A1B95B63DCAA008C8E09BF3CE2B509D01095695","source_posted_at":"2026-09-12T15:35:14Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"b17be57e-7f69-55dc-aa00-ef834786f305","company_id":"c979f4e9-038d-5fb2-9a83-7b11a8426a22","title":"Applied AI Engineer","location":"Melbourne CBD, Melbourne","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"JD excerpt from freehire:adzuna; read the complete posting at https://www.adzuna.com.au/details/5879827727\n\nAbout the job\nWe build production AI agent systems for enterprise clients across financial services, health, government and telco, where “it worked in the demo” isn’t good enough. This isn’t prompt engineering or wiring an LLM to a vector database. You’ll be doing harness design, loop engineering, context engineering and spec-driven builds: the actual discipline behind agents that hold up in production, under audit, at a client that can’t tolerate a shadow AI incident.\nThis is also DX1’s feeder role into our Forward-Deployed Engineer programme. Engineers who build well here, meet the FDE selection criteria and complete the certification pathway are on track for conditional promotion into FDE, where you embed directly with clients and own delivery end to end.\n\nKey Responsibilities\n\n• Design and build production-grade AI systems: agentic architectures, multi-model orchestration, RAG pipelines, tool use and MCP","source_board":"freehire:adzuna","source_external_id":"applied-ai-engineer-dx1-oib67ps7","source_url":"https://www.adzuna.com.au/details/5879827727","source_posted_at":"2026-09-12T00:54:30Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"7c76f885-aad7-5589-b568-2cef077876a2","company_id":"927d8544-13d6-53d9-8806-5e7c5d74187a","title":"AI Engineer: Generative AI & Cloud Data Solutions","location":"Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__121420622__7084\n\nOne51 is a specialist Data, Analytics & AI consulting firm helping organisations unlock value from their data through modern platforms, analytics, reporting, and AI-driven solutions. We partner with clients across industries to design and deliver scalable, high-impact data solutions using technologies such as Microsoft Fabric, Azure, Databricks, Snowflake, and modern cloud data platforms.\nAt One51, we combine deep technical expertise with a pragmatic consulting approach. Our team works closely with clients to solve real business problems, modernise data environments, and enable better decision-making through trusted data and AI-driven insights.\nWe are looking for an innovative and technically skilled AI Engineer to join our growing consulting team. This role is ideal for someone passionate about designing, developing, and deploying AI and Generative AI solutions that create measurable business value.\nAs an AI Engineer at One51, you will work across a range of","source_board":"freehire:whatjobs-au","source_external_id":"ai-engineer-generative-ai-cloud-data-solutions-one51-data-analytics-ai-consulting-6itucqpi","source_url":"https://au.whatjobs.com/pub_api__cpl__121420622__7084","source_posted_at":"2026-09-05T11:57:31Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"a06ebe7f-6b9a-5097-8db1-eb4e21a5cfa4","company_id":"b573450b-e74f-5131-83de-2fd0883cd660","title":"AI-Augmented Full Stack LLM-AI Developer - React, Django; PostgreSQL","location":"South Australia, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__121136398__7084?geoID=5\n\nExpertEase AI is a high-velocity startup at the forefront of AI innovation, building a powerful no-code AI agent creation platform that enables organizations to launch multilingual chat and voice agents in seconds. We're supported by Microsoft, Amazon AWS and NVIDIA as a rising technology partner. Our mission is to democratize access to advanced conversational AI and empower business teams to build custom AI agents without writing a single line of code.\nWe operate in sprints, not marathons, delivering cutting-edge solutions that transform how businesses operate through AI-augmented automation.\nOpportunity to join ExpertEase AI;\nas an AI-Augmented Full Stack Developer and help build the future of no-code AI platforms. We're expanding our founding engineering team. This is mid-senior role require minimum 3 years professional experience.\nMultiple opportunities available across Adelaide office. We need a technical generalist who can","source_board":"freehire:whatjobs-au","source_external_id":"ai-augmented-full-stack-llm-ai-developer-react-django-postgresql-experteaseai-gg6h47uc","source_url":"https://au.whatjobs.com/pub_api__cpl__121136398__7084?geoID=5","source_posted_at":"2026-09-03T07:15:08Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"f5204ff3-1b7f-5a89-9503-e3c43e8dbacc","company_id":"3e114794-fa71-59a8-bf7b-2f7565a97efd","title":"AI engineer intern","location":"Barton, South Canberra","job_type":"internship","industry":"AI & Software","career_id":"ml-engineer","experience_level":"intern","description":"JD excerpt from freehire:adzuna; read the complete posting at https://www.adzuna.com.au/details/5849941216\n\nCompany Description SecureT Solutions Pty Ltd is a technology-focused company dedicated to building secure, reliable, and intelligent software solutions for clients in both public and private sectors. Based in Canberra, the organization works on projects that leverage advanced computing and data-driven approaches to improve operational efficiency and security. Team members collaborate across disciplines to design, build, and deploy innovative tools that address complex real-world problems. The …","source_board":"freehire:adzuna","source_external_id":"ai-engineer-intern-securet-solutions-6b4sdxpv","source_url":"https://www.adzuna.com.au/details/5849941216","source_posted_at":"2026-08-21T06:28:13Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"6eb3a5f8-8672-5cf3-b06e-6043670fb8ab","company_id":"cca94b31-c9cd-584d-b51f-f0a590d943c2","title":"Machine Learning Engineer Intern, Data Trust & Safety (Australia) - 2026 Start","location":"Sydney, Australia","job_type":"internship","industry":"AI & Software","career_id":"ml-engineer","experience_level":"intern","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__115208905__7084?geoID=15513\n\nResponsibilities\nTeam Introduction\n\nBuilding a world where people can safely discover, create and connect. The Trust & Safety (T&S) team at TikTok helps ensure that our global online community is safe and empowered to create and enjoy content across all of our applications. We have invested heavily in human and machine‑based moderation to remove harmful content quickly and often before it reaches our general community.\nInternships at TikTok aim to offer students industry exposure and hands‑on experience. Watch your ambitions become reality as your inspiration brings infinite opportunities at TikTok.\nCandidates can apply to a maximum of two positions and will be considered for jobs in the order you apply. The application limit is applicable to TikTok and its affiliates' jobs globally. Applications will be reviewed on a rolling basis - we encourage you to apply early.\nKey Responsibilities\n\n• Build industry‑leading content safety","source_board":"freehire:whatjobs-au","source_external_id":"machine-learning-engineer-intern-data-trust-safety-australia-2026-start-tiktok-63f55uy3","source_url":"https://au.whatjobs.com/pub_api__cpl__115208905__7084?geoID=15513","source_posted_at":"2026-08-14T19:03:46Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"b5f15deb-854e-59bb-a3da-fa8cb8a13b61","company_id":"1bdf4c53-61bb-5593-a880-f8ef9158b3b1","title":"Applied AI Engineer, Internal Tools","location":"New South Wales, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119849524__7084?geoID=2\n\nDo you want to shape the future of fintech and healthtech? Energized by challenges and inspired by bold goals? Ready to elevate your career alongside driven and talented colleagues? If that sounds like you, explore a career at Alegeus today. Opportunity Happens Here.\n\nAPPLIED AI ENGINEER, INTERNAL TOOLS\n\nJoin our team at Alegeus, where you’ll experience unmatched opportunity and a culture that cares deeply about succeeding together. As a Applied AI Engineer, Internal Tools, you’ll build and scale AI-powered tools, workflows, and solutions that transform how our teams work—reducing manual effort, accelerating productivity, and driving smarter execution across the enterprise. Collaborate with dedicated colleagues, embrace a spirit of innovation, and build an enriching career with us.\n\nOPPORTUNITY HAPPENS HERE — REALIZE YOURS\n\nAlongside the best and the brightest, you will regularly:\n\n• \nIdentify high-impact opportunities to transform","source_board":"freehire:whatjobs-au","source_external_id":"applied-ai-engineer-internal-tools-alegeus-iw3omb7w","source_url":"https://au.whatjobs.com/pub_api__cpl__119849524__7084?geoID=2","source_posted_at":"2026-08-13T12:00:39Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"af534de8-19f2-55fd-8887-2efd0f3f87a5","company_id":"1e0dde71-2661-5191-94b5-778654e87193","title":"Applied AI Engineer - ANZ","location":"New South Wales, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119718141__7084?geoID=2\n\nWe are an applied AI lab building end-to-end software agents.\nWe're the makers of Devin, the first AI software engineer.\nOur team is extremely talent-dense. Among our founding team, we have world-class competitive programmers, former founders, and leaders from companies at the cutting edge of AI including Scale AI, Palantir, Cursor, Waymo, Tesla, Lunchclub, Modal, Google DeepMind, and Nuro.\nBuilding Devin is just the first step—our hardest challenges still lie ahead.\nAbout the Role\nApplied AI Engineers are how Cognition operationalizes AI modernization at the enterprise level. You don't demo Devin - you deploy it. You embed with engineering teams, integrate agentic workflows into how they actually build and ship, and drive the kind of measurable productivity gains that make adoption irreversible.\nAs one of our first Applied AI Engineers, you'll also shape the function itself - turning individual customer","source_board":"freehire:whatjobs-au","source_external_id":"applied-ai-engineer-anz-neura-market-z4tj5la5","source_url":"https://au.whatjobs.com/pub_api__cpl__119718141__7084?geoID=2","source_posted_at":"2026-08-11T13:03:04Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"f26aa57d-47dc-5712-a115-55156020d836","company_id":"a77986b5-230b-523c-88a0-ef0bd454cc3d","title":"Graduate AI Engineer","location":"Australia","job_type":"graduate","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__118402443__7084\n\nEARTH AI is a fast-growing technology company transforming the way critical metals are discovered.\n\nFounded in Sydney in 2016, we use cutting- edge AI and exploration technology to discover new mineral deposits with unmatched efficiency and sustainability. Our mission is to secure the future of technology and infrastructure by responsibly sourcing the metals essential for global advancement.\n\nOur vision is to become the world’s most advanced, efficient, and responsible metal commodity company by discovering and owning the majority of future metal deposits.\n\nAbout the Role\n\nEARTH AI is seeking Graduate AI Engineers to support the development of applied AI and machine learning systems for mineral exploration.\n\nThis role is suited to recent graduates and early-career candidates with up to 2 years of professional experience.\n\nWorking closely with our senior AI researcher, data engineers, and geoscientists, you will contribute to practical,","source_board":"freehire:whatjobs-au","source_external_id":"graduate-ai-engineer-earth-ai-2ww2py3t","source_url":"https://au.whatjobs.com/pub_api__cpl__118402443__7084","source_posted_at":"2026-08-11T04:01:26Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"a2c338a0-36d0-5c7c-b9af-cb849f898ddb","company_id":"53063333-9571-5619-9cdc-bf5e3d59c22f","title":"AI Engineer (Agentic Systems)","location":"Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__118076106__7084\n\nWe are looking for an AI Engineer to join our core team to accelerate the development of the Governa AI product.\n\nThis is not a role for someone who simply integrates API endpoints. We are building complex, multi-agent systems that require a deep understanding of state management, concurrency, reliability, and production-grade AI architecture.\n\nYou will be responsible for architecting agentic workflows, optimising our Retrieval-Augmented Generation (RAG) pipelines, and ensuring that AI interactions are performant, secure, and observable in production environments.\n\nTechnical Stack & Responsibilities\n\n1. Agentic Design & Orchestration\n\n• Design and implement sophisticated agentic workflows using LangChain and LangGraph\n\n• Apply agentic design patterns (Reflection, Planning, Tool Use) to solve non-linear problems\n\n• Build and maintain high-performance backend services using FastAPI\n\n• Optimise","source_board":"freehire:whatjobs-au","source_external_id":"ai-engineer-agentic-systems-chandler-holdings-7dl4dvsl","source_url":"https://au.whatjobs.com/pub_api__cpl__118076106__7084","source_posted_at":"2026-08-11T04:01:25Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"50328ca5-57da-5e40-ab84-3ded32ba4661","company_id":"679c9036-d291-5635-86c3-9570bf92821a","title":"Software Engineer - AI/ML","location":"Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__117132394__7084\n\nWant to Use AI to Tackle Complex, Real-World Problems?\n\nJoin Avertro, a venture-backed cybersecurity startup building a platform that empowers security leaders to manage cyber risk with confidence. We’re tackling one of the industry’s hardest challenges: giving CISOs and boards trustworthy, actionable answers, fast.\n\nWe’re on the lookout for an Software Engineer - AI/ML who balances strong AI/ML fundamentals with hands‑on-software engineering experience. You’ll work at the intersection of LLMs, data pipelines, and production cloud infrastructure; building capabilities that security leaders rely on every day.\n\nIf you're looking to build real AI that goes beyond theory, and work at the intersection of NLP, data enrichment, and impactful product design, this could be the role for you.\n\nThe Opportunity\n\nAs a Software Engineer - AI/ML, you’ll build the AI capabilities at the core of our platform - from retrieval‑augmented chatbots","source_board":"freehire:whatjobs-au","source_external_id":"software-engineer-ai-ml-avertro-dukwo5ao","source_url":"https://au.whatjobs.com/pub_api__cpl__117132394__7084","source_posted_at":"2026-08-10T15:01:14Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"2c125cc8-f01e-5368-bafe-0f9144f91b66","company_id":"7dfb176a-aa49-5af2-8c59-8cda7b1547fa","title":"AI / ML Engineer","location":"Queensland, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119389211__7084?geoID=4\n\nAI / ML Engineer at Easy Authoring. About the role In this position, you will be involved in AI initiatives that span various industries, including commercial, space, and defense.\nYou will join a compact and talented engineering team where your input will be recognized and appreciated.\nThis role offers real opportunities for career advancement as the company expands.\nKey facts\n\n• Location: Brisbane CBD, Brisbane\n• Engagement: Permanent, full-time\n• Team: Engineering Team\nWhat you'll do\n\n• Contribute to the development and implementation of AI solutions across multiple sectors.\n• Collaborate with team members to ensure project goals are met efficiently and effectively.\nRequirements\n\n• A degree in Computer Science, Engineering, or a related field.\n• At least 3 years of experience in AI and machine learning.\n• Proficiency in programming languages such as Python and","source_board":"freehire:whatjobs-au","source_external_id":"ai-ml-engineer-easy-authoring-z7vhh5mn","source_url":"https://au.whatjobs.com/pub_api__cpl__119389211__7084?geoID=4","source_posted_at":"2026-08-10T14:02:16Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"fb83515a-9e68-5af9-92f2-d95201d09d98","company_id":"365a2cde-355b-598c-a052-2f1ff54a7c5b","title":"AI Engineer","location":"Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119387506__7084?geoID=16318\n\nAI Engineer at The Network IT\nAbout the role\nWe are seeking an AI Engineer to join our team on a 12-month fixed-term contract, with the potential for extension. This position offers the chance to work on significant AI and automation projects that will have a broad impact across the organization. You will enjoy working in our stunning offices with views of the Sydney Harbour, located in the vibrant CBD.\nKey facts\nLocation: The Rocks, Sydney Engagement: Contract, 12 months Team: Not specified\nWhat you'll do\n\n• Contribute to the development and implementation of AI solutions that enhance operational efficiency.\n• Collaborate with cross-functional teams to identify opportunities for automation and AI integration.\nRequirements\n\n• A degree in Computer Science, Engineering, or a related field.\n• At least 3 years of experience in AI and machine learning development.\n• Proficiency in Python and","source_board":"freehire:whatjobs-au","source_external_id":"ai-engineer-the-network-it-veopcymv","source_url":"https://au.whatjobs.com/pub_api__cpl__119387506__7084?geoID=16318","source_posted_at":"2026-08-10T14:02:15Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"d25e25df-3786-5a63-8279-638cec2e63d7","company_id":"7c1a6375-96ad-5652-9f3f-76609c6944ac","title":"Machine Learning Engineer","location":"Victoria, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119386599__7084?geoID=7\n\nFor more than 50 years, ENSCO has been providing leading-edge engineering, science and advanced technology solutions to governments and private industries worldwide.\n\nENSCO prides itself in creating and applying advanced technologies for mission success. We provide systems engineering, integration, and advanced technology services to transform the future safety, security, and resiliency of critical missions on the ground, in the air, in space, and in the information systems that connect these domains.\n\nLearn more about ENSCO.\n\nPosition Description\n\nENSCO, Inc. is seeking a Machine Learning Engineer with direct experience and applications with using Machine Learning (ML) and Deep Learning (DL) models, frameworks, architectures, pipelines, and advanced data analytics, to address difficult problem sets. Work closely with other senior scientist to understand problem sets, physical data feature sets and parameters. The successful candidate must have","source_board":"freehire:whatjobs-au","source_external_id":"machine-learning-engineer-ensco-inc-we4utzn5","source_url":"https://au.whatjobs.com/pub_api__cpl__119386599__7084?geoID=7","source_posted_at":"2026-08-10T14:02:14Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"580d9bc2-c7f2-5a2c-b8d9-3159d9b48459","company_id":"4ca141b6-bf36-54b7-a628-fd1ed8686ccf","title":"AI Engineer","location":"Victoria, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"1 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119538726__7084?geoID=7\n\nAt Intelligen, we’re building something different. Over the past three years, we’ve evolved from a bold startup to a trusted partner for some of Australia’s most complex data transformations. We’ve helped organisations move from legacy to modern platforms, embedded governance into decision-making, and are bringing AI into the hands of the business, responsibly and at speed.\n\nNow, as we scale into our next phase, we’re focused on helping organisations move beyond isolated AI experiments and turn promising ideas into practical solutions. Our approach brings together the right problem, the right people and lightweight technology to create outcomes users can understand, trust and adopt.\n\nWe’re looking for an AI Engineer who can support our client apply business logic to narrow in on AI use cases of value, build practical workflows and agents, and keep moving until the solution works.\n\nThis is a hands‑on role for a curious problem solver who can work with","source_board":"freehire:whatjobs-au","source_external_id":"ai-engineer-intelligen-pty-ltd-h35fagdf","source_url":"https://au.whatjobs.com/pub_api__cpl__119538726__7084?geoID=7","source_posted_at":"2026-08-10T14:02:13Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"724983f3-6136-5da1-a534-d584ac2d651a","company_id":"40c3c80a-4c06-5cb3-ae1b-f33db733d74f","title":"AI Engineer","location":"Victoria, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"1 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119655304__7084?geoID=7\n\nAbout SkillfieldSkillfield is a specialist technology consultancyoperatingat the intersection of cyber, data and AI. We partner with enterprise clients to protect,transformand empower their organisations with forward-thinking solutions. Our reputation is built on outcomes, not effort.\nThe Opportunity\nContract - 1 year, fixed term contract\nWe’re seeking an AI Engineer with a passion for experimentation and innovation to join our growing team. In this role, you’ll work on AI use cases and help shape the future of applied machine learning and generative AI. You’ll collaborate with our client's multidisciplinary team to evaluate and validate AI use cases before full-scale implementation. This role involves assessing technical feasibility, estimating ROI, and building proof-of-concepts to demonstrate value.\nWhatYou’llDo\n\n• Rapidly prototype AI use cases such as summarisation, forecasting, and trend detection\n• Work closely with","source_board":"freehire:whatjobs-au","source_external_id":"ai-engineer-skilledfield-ieb3dmet","source_url":"https://au.whatjobs.com/pub_api__cpl__119655304__7084?geoID=7","source_posted_at":"2026-08-10T14:02:12Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"c599847b-0c4c-5d0c-9f8a-d132bb8c2129","company_id":"bc5272f8-8b52-50e1-87c4-76ede6660f0f","title":"AI Engineer","location":"Victoria, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"1 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119537324__7084?geoID=7\n\nAbout Skillfield\nSkillfield is a specialist technology consultancy operating at the intersection of cyber, data and AI. We partner with enterprise clients to protect, transform and empower their organisations with forward-thinking solutions. Our reputation is built on outcomes, not effort.\nThe Opportunity\nContract - 1 year, fixed term contract\nWe’re seeking an AI Engineer with a passion for experimentation and innovation to join our growing team. In this role, you’ll work on AI use cases and help shape the future of applied machine learning and generative AI. You’ll collaborate with our client's multidisciplinary team to evaluate and validate AI use cases before full-scale implementation. This role involves assessing technical feasibility, estimating ROI, and building proof-of-concepts to demonstrate value.\nWhat You’ll Do\n\n• Rapidly prototype AI use cases such as summarisation, forecasting, and trend","source_board":"freehire:whatjobs-au","source_external_id":"ai-engineer-skillfield-ovrtmzga","source_url":"https://au.whatjobs.com/pub_api__cpl__119537324__7084?geoID=7","source_posted_at":"2026-08-10T14:02:12Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"08d9ce78-509b-58cc-8c8e-5f88c5009997","company_id":"e4918786-5444-5ed5-97d1-462bbfeba66c","title":"Machine Learning Engineer - AI Team","location":"Queensland, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"3 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119390537__7084?geoID=4\n\nMachine Learning Engineer - AI Team\n\nBrisbane CBD | Hybrid (2-3 days in office)\n\nSalary: $100K-$170K + Super\n\nCertus Recruitment Group is partnering with an innovative organisation in Brisbane to hire a Machine Learning Engineer to join their growing AI team.\n\nYou’ll work across NLP, computer vision, generative AI, and applied ML - building real-world solutions that sit at the intersection of data, design, and user experience.\n\nIf you enjoy shaping ideas from prototype to production and collaborating with cross‑functional teams, this role offers genuine impact and technical breadth.\n\nResponsibilities\n\n• Develop and fine-tune ML models across NLP, computer vision, and generative AI.\n\n• Adapt and apply foundation models (OpenAI, Anthropic, Cohere) for targeted use cases.\n\n• Build and maintain data pipelines, experiment tracking, and model deployment workflows.\n\n• Integrate ML capabilities into","source_board":"freehire:whatjobs-au","source_external_id":"machine-learning-engineer-ai-team-certus-recruitment-group-xa3z4yol","source_url":"https://au.whatjobs.com/pub_api__cpl__119390537__7084?geoID=4","source_posted_at":"2026-08-10T14:02:12Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"3a691f02-f673-5888-9996-da337d23b6f1","company_id":"6d4b762d-6f7a-5635-b079-36eab4c54bee","title":"Machine Learning Engineer","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"2 years minimum","description":"JD excerpt from freehire:whatjobs-au; read the complete posting at https://au.whatjobs.com/pub_api__cpl__119537666__7084?geoID=15513\n\nMachine Learning Engineer\nThis range is provided by NineTech. Your actual pay will be based on your skills and experience — talk with your recruiter to learn more.\nBase pay range\nA$90.00/hr - A$90.00/hr\nDirect message the job poster from NineTech\nWe’re urgently seeking a Senior DevOps ML Engineer with a rare combination of DevOps leadership, software engineering depth, and MLOps expertise.\nThe client requires someone with DevOps leadership, coding skills akin to a seasoned backend engineer, and ability to optimize AI systems with precision.\nYou will be responsible for the end-to-end design, deployment, and operation of AI platforms.\nExpect to split your time approximately as follows: 60% DevOps/AI infrastructure, 30% backend coding, and 10% MLOps/model lifecycle tasks.\nOne week, you may be","source_board":"freehire:whatjobs-au","source_external_id":"machine-learning-engineer-ninetech-kfsr2ucs","source_url":"https://au.whatjobs.com/pub_api__cpl__119537666__7084?geoID=15513","source_posted_at":"2026-08-10T14:02:11Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"de4cf1b3-c7f7-5f50-a8a0-450c0ba94d3a","company_id":"fbd25e99-fcf9-55ec-ada3-5e60d6cbcfc8","title":"VIE AI Engineer Consultant","location":"Sydney NSW","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Company Description\n\nSia is a next-generation, global management consulting group. Founded in 1999, we were born digital. Today our strategy and management capabilities are augmented by data science, enhanced by creativity and driven by responsibility. We’re optimists for change and we help clients initiate, navigate and benefit from transformation. We believe optimism is a force multiplier, helping clients to mitigate downside and maximize opportunity. With expertise across a broad range of sectors and services, our 3,000 consultants serve clients worldwide from 48 locations in 19 countries. Our expertise delivers results. Our optimism transforms outcomes. \n\nJob Description\n\nWithin the AI & Data Business Unit, you will help organizations transform their business processes through Generative and Agentic AI. Working alongside Data Scientists, Machine Learning Engineers, Solution Architects, and Platform Engineers, and working step-by-step with customers, you will design, build, and deploy enterprise-grade AI systems that create measurable business value. Your key responsibilities include: \n\n• \nAssist the GenAI Solution Architect in designing scalable and secure AI solutions. \n\n• \nDevelop applications powered by foundation models, both self-managed and API-accessible, that meet business needs and comply with applicable regulations (GDPR, EU AI Act, model licenses, etc.). \n\n• \nDesign prompting and orchestration strategies to improve reasoning, controllability, reliability, and user experience. \n\n• \nDesign and optimize Retrieval-Augmented Generation (RAG) systems leveraging enterprise knowledge sources, semantic search, and source attribution. \n\n• \nDesign, implement, and optimize agentic AI systems using orchestration frameworks such as LangGraph, CrewAI, AutoGen, Semantic Kernel, or equivalent. \n\n• \nDevelop AI agents capable of tool usage, workflow orchestration, planning, reasoning, memory management, and human-in-the-loop interactions. \n\n• \nArchitect AI solutions integrating enterprise systems, APIs, databases, and knowledge repositories. \n\n• \nEvaluate and select the most appropriate models based on business requirements, performance, latency, and cost constraints. \n\n• \nMonitor AI system performance in production and contribute to observability, evaluation, and governance practices. \n\n• \nConduct research on the latest advances in foundation models, multimodal AI, and agentic AI systems. \n\nQualifications\n\nYou hold a Master’s degree from an engineering school or an advanced degree in computer science, engineering, or artificial intelligence and you have at least one year of technical experience building creative AI solutions. \n\nYou are proficient in Python programming and code versioning, and ideally have experience with Generative AI frameworks (LangChain, LangGraph, RAG), advanced prompting techniques, and are familiar with Open-Source AI ecosystems (Antropic, OpenAI) as well as cloud-native architectures and modern AI deployment practices. \n\nYou want to get involved and quickly take on responsibility for high-value-added assignments within a dynamic organization. You are passionate about pushing the boundaries of AI technology and making a significant impact in enabling our customers to create GenAI-powered applications with confidence and a fast time to market. \n\nFinally, are you curious and enjoy working as part of a team? Do you want to join a dynamic and motivating professional environment? Do you share our values of excellence, entrepreneurship, innovation, sharing, kindness, and work-life balance? \n\nAre you fluent in English? \n\nThen join us! \n\nAdditional Information\n\nPlease send us your CV in English. \n\nPlease ensure you meet the VIE contract eligibility criteria as established by Business France:\n\n• Anyone over 18 and under 28 years of age on the date of registration may apply for an International Volunteer Program (VIE).\n\n• Departure on assignment must take place no later than the day of your 29th birthday. Beyond this, no exceptions are granted.\n\n• You must hold French or European nationality (a national of a Member State of the European Economic Area, which comprises the 28 Member States of the European Union, Norway, Iceland, and Liechtenstein) or Monégasque nationality.\n\n• You must be in compliance with the national service obligations of the country of which you are a national.\n\n• You must be in possession of your civic rights and have a clean criminal record.\n\nSia is an equal opportunity employer. All aspects of employment, including hiring, promotion, remuneration, or discipline, are based solely on performance, competence, conduct, or business needs.","source_board":"freehire:seek","source_external_id":"vie-ai-engineer-consultant-sia-partners-vijab5ut","source_url":"https://www.seek.com.au/job/94739743","source_posted_at":"2026-09-18T13:14:17Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"5d80370a-5c93-592f-ae92-c31202c8592b","company_id":"f9ab1ff4-8241-5225-bda0-47b85659c9bf","title":"AI/ML Engineer","location":"Melbourne, VIC, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"We are seeking 6 talented and forward-thinking AI/ML Engineers to design, build, and scale enterprise-grade artificial intelligence and machine learning solutions. You will be responsible for taking models from initial prototype to robust, production-level deployment and integrating these solutions within Downer’s broader technology landscape. \n\nThis role is suited to collaborative, quality-focused engineers who enjoy building, testing and improving production-ready AI solutions with an agentic first mindset. You will work across enterprise scale AI platforms including Azure Databricks and MS Foundry and be well versed in engineering tools such as Claude Code, Codex, Cursor and/or Github Copilot.\n\nYou’ll be working within product delivery teams and will collaborate with architecture, cyber security, data governance and platform engineering teams as well as being a key influencer with business stakeholders. \n\nThis position is Australia-based, with Sydney, Melbourne or Brisbane preferred and may require occasional travel to various Downer sites.\n\nAbout the Role\nIn this role, you will:\n\n• Design, build, test and deploy enterprise grade AI solutions and agentic workflows across MS Azure and Databricks ecosystems.\n• Using manual and spec-driven techniques, develop clean, testable and well-documented Python, C# and SQL code that meets engineering standards and supports long-term supportability.\n• Develop integrated PDLC and DDLC agent workflows which delivery software applications, data pipelines and products.\n• Build AI solutions using frontier and open weight models using RAG, VectorDBs, Knowledge Graphs and MCP servers.\n• Use Azure AI Foundry, Databricks Mosaic AI and approved AI engineering tools to support solution development and delivery.\n• Contribute across the delivery lifecycle, including problem framing, data exploration, prototyping, feature engineering, model evaluation, deployment, monitoring and support.\n• Design and maintain MLOps pipelines, including CI/CD for machine learning, automated model training, evaluation gates, deployment and monitoring.\n• Manage experiment tracking, model versioning and reproducibility through the Databricks MLflow model registry.\n• Implement solution performance monitoring with evaluation agents for drift detection, hallucination, and model performance degradation.\n• Apply spec-driven development, DevOps, secure-by-design, responsible AI and human-in-the-loop review practices.\n• Contribute to engineering standards, code reviews, prompt reviews, technical design sessions and agile delivery ceremonies.\n• Produce and maintain technical documentation, including architecture decision records, runbooks, model cards, data lineage records and pipeline documentation.\n• Support and mentor junior engineers through knowledge sharing, pairing and agent-assisted delivery walkthroughs.\n• Work with architecture, governance and cyber security teams to ensure solutions meet Downer’s enterprise, security and responsible AI standards.\n• Contribute to cost optimisation and FinOps practices across Azure Databricks and Azure AI Foundry.\n\nThis is an opportunity to contribute to Downer’s uplift in AI-native delivery while developing your technical depth across modern AI/ML engineering, agentic workflows and governed enterprise AI.\n\nOur Ideal Candidate\nYou are a hands-on engineer who enjoys transforming complex problems into practical, reliable and maintainable solutions.\n\nYou are curious about emerging AI engineering tools, a coder at heart but take pragmatic and responsible approaches to using AI tooling to accelerate development in enterprise environments. You are comfortable collaborating with product, architecture, security, governance and business stakeholders, and can explain technical concepts, limitations and trade-offs clearly to both technical and non-technical audiences.\n\nWhat You Will Bring\n\n• A tertiary qualification in Computer Science, Computer Engineering, Software Engineering, Information Technology, Data Science, Mathematics, Statistics, quantitative analysis or a related discipline.\n• Relevant industry certifications in Azure AI, Databricks, GitHub, software engineering, DevOps, security or cloud data platforms will be highly regarded. \n• At least five years’ total experience across software and/or data engineering or related technical field.\n• At least two years relevant hands-on experience developing advanced analytics, machine learning or generative AI solutions for production environments.\n• Practical experience with Azure and Databricks ecosystems, including exposure to Azure AI Foundry, Databricks Mosaic and Genie Code.\n• Familiarity with model hosting in platforms such as Azure AI Foundry, Databricks Mosaic AI and AWS Bedrock is highly regarded.\n• \nExperience with AI engineering tools such as Claude Code, Codex, Cursor, GitHub Copilot and Copilot Studio is highly regarded. \n• \nExperience in DevOps engineering, CI/CD, secure-by-design principles and FinOps controls recognising the importance of balancing token-economics with performance.\n• Familiarity with orchestration frameworks such as CrewAI, Strands Agents and Microsoft Agent Framework is valued, as is familiarity with spec-driven development, agentic product delivery lifecycle practices and agentic business workflows.\n• Strong hands-on capability in Python, C#, SQL, Git-based version control, automated testing, code review and production-quality engineering practices.\n• \nPractical understanding of platform controls implemented through Unity Catalog, Microsoft Purview and Agent 365 as part of an enterprise Data & AI governance ecosystem.\n\nYou are known for your curiosity, sound technical judgement and commitment to producing secure, reliable and explainable AI solutions that deliver meaningful business outcomes.\n\nBenefits Of Working with Downer\n\n• Work with an ASX-listed company, working with market leaders.\n• Grow your career with us through personal and professional development and continuous learning: \n\n• Professional development programs\n• Access to professional memberships and industry networks\n• Be part of a team that cares, with support that is flexible around employee wellbeing needs: \n\n• Flexible work arrangements\n• Parental leave\n• Employee Assistance Program\n• Programs promoting diversity and inclusion\n• A range of corporate benefits, including: \n\n• Discounted services (car hire, hotels, insurance, retail stores, gyms)\n\nWhy Downer?\nAs a trusted name in infrastructure, transport, facilities management, and construction, Downer is committed to delivering projects that create a lasting, positive legacy.\nWe're committed to building a team that reflects the diverse communities we serve, and we welcome people of all ages, genders, sexual orientations, cultures, abilities, and lived experiences. We especially encourage applications from those whose voices have traditionally been underrepresented in our industry, including women, Aboriginal and Torres Strait Islander Peoples, Māori and Pasifika Peoples, veterans, people with disability, and neurodivergent individuals.\n\nEven if your experience doesn't align perfectly with this role, we'd still like to hear from you. If it feels like the right fit, apply — potential counts, and so do you.\n\nAs a WORK180 Endorsed Employer, we support flexibility that works for your life, inclusive leadership that values your voice, and equitable access to opportunity so you can do your best work and bring your whole self to it.","source_board":"freehire:oracle","source_external_id":"ai-ml-engineer-downer-3e5zxlsu","source_url":"https://fa-exfs-saasfaprod1.fa.ocs.oraclecloud.com/hcmUI/CandidateExperience/en/sites/jobsearch/job/736780","source_posted_at":"2026-09-18T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"17ed6bfa-35c1-5eb4-b457-c3357cf2bf69","company_id":"74f244dc-3cc6-593b-9e3d-960009bc986b","title":"AI Engineer","location":"Sydney","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Line of ServiceAdvisory\n\nIndustry/SectorNot Applicable\n\nSpecialismAnalytics\n\nManagement LevelManager\n\nJob Description & Summary\n\nEducation (if blank, degree and/or field of study not specified)Degrees/Field of Study required:\n\nDegrees/Field of Study preferred:\n\nCertifications (if blank, certifications not specified)\n\nRequired Skills\n\nOptional SkillsAccepting Feedback, Accepting Feedback, Active Listening, Analytical Thinking, Artificial Intelligence, Big Data, C++ Programming Language, Coaching and Feedback, Communication, Complex Data Analysis, Creativity, Data-Driven Decision Making (DIDM), Data Engineering, Data Lake, Data Mining, Data Modeling, Data Pipeline, Data Quality, Data Science, Data Science Algorithms, Data Science Troubleshooting, Data Science Workflows, Deep Learning, Embracing Change, Emotional Regulation {+ 22 more}\n\nDesired Languages (If blank, desired languages not specified)\n\nTravel RequirementsNot Specified\n\nAvailable for Work Visa Sponsorship?No\n\nGovernment Clearance Required?No\n\nJob Posting End DateSeptember 20, 2026","source_board":"freehire:workday","source_external_id":"ai-engineer-pwc-7swgqpbz","source_url":"https://pwc.wd3.myworkdayjobs.com/NonPublic_Postings/job/Sydney/AI-Engineer_707912WD","source_posted_at":"2026-09-17T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"8608c29b-23db-5c54-9a43-876036d60278","company_id":"3f073ab2-ce29-5e6b-b7d2-2a22e57be75c","title":"AI Data Science/ Machine Learning Engineer (Australia)","location":"Sydney, New South Wales, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"The Organization \nAt TWG/ Vergence AI, we drive innovation and business transformation across a range of industries—including financial services, insurance, technology, media, and sports—by leveraging data and AI as core assets. Our AI-first, cloud-native approach delivers real-time intelligence and interactive business applications, empowering informed decision-making for both customers and employees.\nWe prioritize responsible data and AI practices, ensuring ethical standards and regulatory compliance. Our decentralized structure enables each business unit to operate autonomously, supported by a central AI Solutions Group, while strategic partnerships with leading data and AI vendors fuel game-changing efforts in marketing, operations, and product development.\nYou will collaborate with management to advance our data and analytics transformation, enhance productivity, and enable agile, data-driven decisions. By leveraging relationships with top tech startups and universities, you will help create competitive advantages and drive enterprise innovation.\nThe Role \nAs AL/ML Scientist, you will lead the development and implementation of cutting-edge AI solutions to drive significant business impact, including cost optimization and revenue growth. Reporting to the Head of AI Science, you will be a key strategic advisor and a custodian of institutional AI knowledge.\nYou will drive the development of predictive modeling use cases, prioritize AI governance, and champion the ethical and responsible use of AI across the organization. This role requires a deep understanding of AI/ML techniques, strong leadership skills, and the ability to translate complex technical concepts into actionable business strategies.\n\nKey Responsibilities: \n\n• Deliver cutting-edge AI/ML capabilities and tools in a project-based capacity to accelerate key business objectives, including cost savings and revenue generation.\n• · Develop advanced AI solutions, including time series forecasting, reinforcement learning, optimization and optimal decision-making, generative AI, speech and conversational AI, and Graph AI.\n• · Champion the exploration and implementation of advanced AI techniques, including time series forecasting, reinforcement learning, optimization, and conversational AI, to address critical business challenges. Stay abreast of emerging trends and technologies, ensuring the organization remains at the forefront of AI innovation.\n• · Serve as a key contributor to the Foundation Model Task Force, driving the development and implementation of foundational AI models that will be leveraged across the organization.\n• · Ensure that all AI initiatives adhere to the highest standards of trust, transparency, safety, and security, fostering ethical AI practices and maintaining regulatory compliance.\n• · Develop and implement AI strategies that align with and accelerate business objectives, delivering tangible outcomes such as improved efficiency, cost reductions, and new revenue streams.\n• · Collaborate with business leaders, technical experts, and cross-functional teams to ensure AI/ML initiatives are integrated effectively and aligned with broader business strategies.\n• · Stay ahead of industry trends and drive continuous improvement by incorporating emerging AI technologies and methodologies into the organization's toolkit, ensuring the company remains at the forefront of AI innovation.\n• · Establish and manage performance metrics for AI/ML projects, ensuring that all initiatives are delivered on time, within scope, and achieve desired business outcomes.\nRequirements\nQualifications: \n\n• Ideally 2+ years experience in data science or developing machine learning models, working on cross-functional teams and managing complex, multi-faceted AI initiatives.\n• · Strong expertise in statistical analysis, machine learning, and data mining, including time series forecasting, reinforcement learning, optimization, and speech or conversational AI.\n• · Proficiency in programming languages such as Python, R, or similar, and experience with data visualization tools.\n• · Excellent leadership, communication, and interpersonal skills.\n• · Ability to think strategically and drive business results through data insights.\n• · Master’s degree or PhD in Data Science, Computer Science, Statistics, Mathematics, or a related field.\nPreferred Qualifications: \n\n• Hands-on experience with enterprise data and AI platforms (e.g., Palantir Foundry or similar), or cloud-based AI/ML tools. \n• Experience applying data science to real business problems through internships, research collaborations, or industry projects. \n• Exposure to AI/ML governance, ethics, or responsible AI practices. \nBenefits\n\n*This job posting is not to be reposted without the explicit permission of TWG AI.","source_board":"freehire:workable","source_external_id":"ai-data-science-machine-learning-engineer-australia-twg-global-qbyvoqcj","source_url":"https://apply.workable.com/j/D1D8145D46","source_posted_at":"2026-09-16T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"5d48e471-1666-5fcd-acc4-b6ad5ae809c4","company_id":"af116472-589c-51ec-9b37-af5f557be5cf","title":"Software Engineer - Machine Learning Frameworks","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"The Machine Learning Frameworks team exists for two reasons: making the research iteration loop as fast and frictionless as possible, and making production run as fast as the hardware allows. Both matter, and figuring out how to do both at once is most of what makes the work fun.\n\nConcretely, we build optimisers, code generators, runtime libraries, and the orchestration layer that runs computation across heterogeneous hardware. The stack spans C++, Rust, Python, MLIR, and CUDA. You don't need to know all of these things but should want to work at this level of the stack.\n\nThe work is broad. Some of it is high-level, looking at the whole compute pipeline, orchestrating the system and creating a cohesive product. Some of it is in the details, getting into hardware behaviour, dissecting compute graphs, squeezing the last bit of performance out of the hot path. Our job is managing the whole stack, top to bottom.\n\nAbout you\n\n• You write production code in a systems language. C++ or Rust, or something close enough that picking them up isn't the hard part. The right tool matters more to you than your favourite one\n\n• You like understanding what a language compiles down to and how it runs on hardware.\n\n• You're comfortable being handed an unfamiliar part of the stack and working it out.\n\n• You like working with stakeholders and you’re good at figuring out what someone actually needs, not just what they asked for\n\n• You've done this commercially. You've owned something in production that other people relied on. Not necessarily big, but something you had to maintain, debug and live with long after you shipped it.\n\nWhat you don't need\n\nA finance background. Exposure to every language we touch. We hire engineers who like to solve the problems our traders face - we'll teach you the context on the ground\n\nAbout Us\n\nIMC is a research-driven trading firm where quantitative modeling, machine learning, and engineering shape how modern markets are traded. A stabilizing force in markets since 1989, we provide liquidity across trading venues, delivering the best outcome in value and risk management to investors. Using our own technology and capital, we build proprietary systems and algorithms that operate across global markets. Our researchers, traders, and engineers work as a collective, combining rapid experimentation, advanced infrastructure, and real-time feedback to turn insight into execution and execution into advantage.","source_board":"freehire:greenhouse","source_external_id":"software-engineer-machine-learning-frameworks-imc-trading-u5lrpnql","source_url":"https://job-boards.eu.greenhouse.io/imc/jobs/4930380101","source_posted_at":"2026-09-15T15:21:55Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"464cc73a-5dde-5dc4-ab35-663d8a5ba8ad","company_id":"c6d121e0-b460-540e-a9bd-b3b185a11fb2","title":"AI Engineer","location":"Perth WA","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Highlights\n\n• Build practical AI products using LLMs, agentic workflows, RAG & semantic search\n• Shape a workforce intelligence platform for energy, resources & infrastructure\n• Join an ASX-listed technology company taking ideas from concept to production\nPosition summary\n\nAQYR is looking for an AI Engineer to build and deploy AI-powered products across recruitment and workforce intelligence.\n\nYou'll work hands-on with LLMs, agentic workflows, RAG, semantic search, matching systems and market intelligence. Your work will help customers understand talent supply, hiring demand, salary benchmarks, workforce risks and the time and difficulty involved in filling roles.\n\nThis is a practical engineering role for someone who enjoys turning complex and unstructured data into useful products. You'll design Python-based services, build AI workflows, improve search and ranking quality, and help take new ideas from prototype to reliable production systems.\n\nYou'll work with technologies including Python, PostgreSQL and AWS services.\nAbout the company\n\nAQYR is a workforce intelligence platform helping organisations make better decisions about talent, hiring and workforce planning.\n\nThe platform combines AI, market intelligence, industry expertise and large-scale workforce data to help customers:\n\n• Understand talent markets and workforce trends\n• Benchmark salaries and assess hiring difficulty\n• Identify available talent and competing employers\n• Improve sourcing, role positioning and hiring strategies\n• Plan for future workforce requirements\n\nAQYR is part of Hiremii Limited (ASX), an Australian technology company focused on improving talent acquisition and workforce decision-making.\n\nIts wholly owned subsidiary, Inverse Group, provides specialist recruitment services to energy and resources organisations in Australia and internationally.\n\nBased in Perth, AQYR works across the energy, resources, infrastructure and technology sectors.\nAbout the role\n\n• Build and deploy AI applications using LLMs and agentic systems\n• Develop RAG, semantic search, matching and ranking capabilities\n• Transform structured and unstructured data into useful workforce insights\n• Build AI workflows that support market analysis, salary benchmarking and workforce planning\n• Create APIs, data pipelines and production services using Python and PostgreSQL\n• Develop evaluation and testing frameworks to measure AI quality\n• Deploy and operate services using AWS\n• Improve system quality, reliability, latency and cost\n• Work closely with the CPO & CTO to solve ambiguous problems and deliver practical solutionsAbout the candidate\n\nYou'll be a strong software engineer with hands-on experience building AI-powered applications. You should be comfortable taking ownership and learning quickly.\n\nYou will ideally have experience with:\n\n• Python application or backend development\n• LLM APIs, prompt design and structured outputs\n• RAG, embeddings, semantic search or information retrieval\n• Agentic or multi-step AI workflows\n• Data pipelines, document processing or information extraction\n• PostgreSQL or another relational database\n• Docker, cloud deployment or AWS\n• Testing, Git, CI/CD and production monitoring\n• Evaluating AI systems and improving output quality\n\nExperience in market intelligence, analytics, recruitment technology, search, ranking or decision-support products would be valuable, but is not essential.\n\nMost importantly, you're motivated by building AI products that solve real customer problems.\n\nWe care more about what you've built and shipped than whether you've worked with every technology in our stack.","source_board":"freehire:seek","source_external_id":"ai-engineer-hiremii-kca5aobt","source_url":"https://www.seek.com.au/job/94633588","source_posted_at":"2026-09-15T02:10:07Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"4fdcd490-c63e-5aac-a264-010332e3d8af","company_id":"9246b960-088f-55b9-8a30-fe3f964e13be","title":"AI Engineer x 2 (AI Innovation Office)","location":"Sydney, NSW, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"• Sydney Location / Hybrid Working. \n\n• Work with some of the brightest minds in the AI space. \n\nWhat is the opportunity?\n\nAt Westpac, we’re building responsible, human-centred AI at enterprise scale — and we’re looking for hands-on AI Engineers who can turn ideas into secure, scalable, production-ready solutions.\n\nYou’ll join our Data, Digital & AI function and work with the Westpac Chief AI Innovation Office to build practical AI capability across technology, data, risk, security, product and business teams.\n\nThis is an engineering-first role for people who can design, code, integrate, test and operationalise AI applications, services, agents and platforms — beyond proofs of concept.\n\nYou’ll bring strong software engineering fundamentals, practical AI/ML experience and the judgement to deliver safely in a complex, regulated enterprise environment.\n\nKey Responsibilities – \n\n• Design, build and ship production-ready AI applications, services, agents and internal tools.\n\n• Integrate foundation models, ML models, RAG, vector stores and AI services into secure enterprise workflows.\n\n• Build pipelines for prompt management, model invocation, grounding, validation and evaluation.\n\n• Embed security, privacy, compliance, model risk and responsible AI guardrails from design to delivery.\n\n• Build testing, evaluation, monitoring, and feedback loops for quality, performance, safety, and cost.\n\n• Optimise latency, reliability, and cost across AI workloads.\n\n• Collaborate with product, data, risk, security, and platform teams to clarify requirements, surface trade-offs, and align priorities for delivery.\n\nEssential Ingredients … \n\n• Hands-on AI engineering experience in large, complex corporate or regulated environments.\n\n• Ability to deal effectively with technical and non-technical stakeholders at all levels. \n\n• Tertiary qualifications in a relevant technology, engineering, computer science, data or related discipline, or equivalent practical experience.\n\n• Strong software engineering background across backend services, APIs and production systems.\n\n• Practical experience operationalising LLM, ML or AI services beyond prototypes or academic projects.\n\n• Hands-on knowledge of RAG, embeddings, vector databases, orchestration and model evaluation.\n\n• Experience with cloud, CI/CD, automated testing, observability and enterprise release practices.\n\n• Understanding of prompt design, evaluation, safety testing and responsible AI practices.\n\n• Ability to balance experimentation speed with engineering quality and safety.\n\n• Comfortable working with diverse stakeholders to triage requests, communicate constraints, and prioritise work based on impact and risk.\n\nWhy join us? \n\nWe’re obsessed with becoming our customers' #1 banking partner for life and we’re looking for people who are passionate about helping us achieve that goal. In return, we’re committed to making Westpac the best place to work in the country. \n\nHere are just a few of the ways we’re already doing that: \n\n• Special offers on banking products and discounts from top brands, including generous employee-only mortgage rates! \n\n• Flexible work arrangements to help you achieve a greater work/life balance, and a variety of leave options including Culture, Lifestyle and Wellbeing leave. \n\n• Tailored learning and development opportunities to help grow your career within the bank. \n\n• Lots of opportunities to ‘give back’ to the Community by getting involved in our many volunteering initiatives. \n\nCreate your future today! \n\nTo get started, simply click on the APPLY or APPLY NOW button. \n\nWe’re all about creating a supportive and inclusive community. We welcome everyone – no matter your age, gender, background, or abilities. We also provide additional support to welcome our veterans, Indigenous Australians and neurodiverse community. \n\nIf you need any adjustments during the recruitment process, you can find out more information and additional contact details by visiting the \"People with Disability and/or needing Accessibility Requirements\" page on our website.","source_board":"freehire:oracle","source_external_id":"ai-engineer-x-2-ai-innovation-office-westpac-75v2xbmn","source_url":"https://ebuu.fa.ap1.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX/job/68817","source_posted_at":"2026-09-14T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"c7321bb7-5f7f-50cb-b2f6-9d22268ae4f3","company_id":"4a026dc6-fe74-5476-a700-7f61b278a0f0","title":"Forward Deployed AI Engineer","location":"Canberra ACT","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Salary: 100-150k base + super\nForward Deployed Engineer – AI\n\nCanberra | Permanent | Hybrid\n\nWe’re working with a leading global consulting organisation building a high-performing AI engineering team in Australia.\n\nThey’re looking for a Forward Deployed Engineer to work directly with strategic clients, turning complex business challenges into production-ready AI solutions.\n\nWork on real-world AI deployments using cutting-edge Anthropic technologies.\n\nPlease note you must be an Australian citizen to be considered for this role.\n\nThe Role\n\nYou’ll sit at the intersection of AI engineering, software development, solution architecture and client delivery.\n\nYou could be:\n\n• \n\nBuilding AI/LLM applications and agentic workflows\n\n• \n\nDesigning integrations, data pipelines and cloud architectures\n\n• \n\nRapidly prototyping and taking solutions into production\n\n• \n\nProviding technical leadership and mentoring engineers\n\n• \n\nWorking directly with senior client stakeholders to shape solutions\n\nAbout You\n\n• \n\nStrong experience with Python, Java, C#, JavaScript/TypeScript or Go\n\n• \n\nExperience building AI/LLM applications in production would be nice but complusory\n\n• \n\nCloud experience across AWS, Azure or GCP\n\n• \n\nExcellent client-facing communication skills\n\nYou don't need to have been an FDE before — Senior Software Engineers, AI Engineers, Solutions Architects and AI Consultants with the right background are all relevant.\n\nWhy Join?\n\nIf you want to move beyond AI prototypes and actually build and deploy AI solutions that make an impact, we'd love to hear from you.\n\nApply now!","source_board":"freehire:seek","source_external_id":"forward-deployed-ai-engineer-the-recruitment-company-kziu52co","source_url":"https://www.seek.com.au/job/94574282","source_posted_at":"2026-09-11T06:03:04Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"309a62ed-3676-5590-a05c-ec610905ff56","company_id":"e2ae69c1-b273-5f47-a5a6-033716e0f434","title":"AI Developer","location":"West Leederville, Western Australia, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"AI Developer\n\n6-Month Fixed Term contract with potential for extension\n\nDenver Technology is a technology consultancy based in Perth, with offices in Brisbane and London. For 35 years we have worked with energy, resources and asset-intensive organisations across Australia and overseas, running projects that hold up in production. We back people who do careful work and explain it well.\n\nThe role\n\nWe want an AI Developer to design, build, deploy and support enterprise AI solutions that lift productivity and help people use AI in their daily work. The role spans AI application and web development, integration, containerisation and DevOps. You will work with business and technology teams to find the AI use cases worth building, ship production-ready solutions, and set them up for other teams to support and scale.\n\nWhat we offer\n\n• Competitive Salaries: Employees can expect competitive and benchmarked salaries, ensuring fair compensation for their skills and contributions. \n\n• Training and Certification Budgets: We invest in the professional growth of our people by allocating budgets for training and certification. \n\n• Employee Assistance Programme: An Employee Assistance Programme is in place to support the well-being and mental health of employees.\n\n• Active Social Club and Social Events: We foster a vibrant social culture with an active social club. \n\n• Regular Celebrations: We take pride in acknowledging and celebrating both our achievements and our people.\n\nWhat you'll do\n\n• Design and build AI-enabled applications, interfaces and agentic workflows using LLMs and enterprise AI platforms.\n\n• Build responsive web applications in React or similar, with reusable front-end components, and integrate them with APIs, AI services and enterprise systems.\n\n• Package and deploy with Docker and OpenShift to CI/CD practice, then monitor, tune and resolve issues.\n\n• Turn business requirements into practical designs, prototypes and delivery plans, and assess feasibility, risk and the scope to scale.\n\n• Apply responsible AI practice: security, privacy, governance and human oversight.\n\n• Produce technical documentation and handover so support teams can run and scale each solution.\n\n• Run demonstrations and walkthroughs, and help teams adopt AI tools.\n\nWhat you need\n\n• Experience building AI-enabled applications with LLMs, generative AI services or enterprise AI platforms.\n\n• Web development in React, JavaScript or TypeScript.\n\n• Experience integrating applications with REST APIs, AI services and enterprise systems.\n\n• Containerisation with Docker and OpenShift or Kubernetes, plus DevOps, source control, automated testing and CI/CD.\n\n• A track record taking prototypes through to secure, maintainable production.\n\n• A tertiary qualification in computer science, software engineering, IT or AI, or equivalent experience.\n\nNice to have\n\n• Open WebUI or similar enterprise AI interface platforms.\n\n• Agentic AI platforms, orchestration frameworks or tool-enabled AI workflows.\n\n• Retrieval-augmented generation, embeddings, vector databases and enterprise search.\n\n• AI governance, model evaluation, privacy, cyber security and responsible AI controls.\n\n• Enterprise technology adoption experience, in a corporate, resources, mining or operational environment.","source_board":"freehire:bamboohr","source_external_id":"ai-developer-denver-g7g3ug5j","source_url":"https://denver.bamboohr.com/careers/139","source_posted_at":"2026-09-11T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"c800b796-7189-5203-a568-d754836c46ba","company_id":"89f16c3f-ed6d-5938-8f5e-c671fcbd22d7","title":"Applied AI Engineer, Australia","location":"Sydney","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About Mistral\nMistral provides full-stack AI solutions: from frontier models to developer tools, applications, and compute. We partner with enterprises tackling the hardest problems across high-stakes industries like finance, manufacturing, defense, healthcare, and the public sector, co-creating customized AI systems that they can run on their terms.\nWe are a dynamic, collaborative team passionate about AI and its potential to transform society. Our diverse workforce thrives in competitive environments and is committed to driving innovation. Our teams are distributed between Europe, North America, Asia and the Middle East. We are creative, low-ego and team-spirited.\n\nThe Role\nAs a Applied AI Engineer on the Applied AI team, you will bridge the gap between Mistral’s cutting-edge AI research and real-world enterprise applications. This role exists to ensure our solutions are robust, scalable, and aligned with both customer needs and Mistral’s technological vision.\nThe Applied AI team is Mistral’s customer-facing technical organization, working directly with enterprise clients from pre-sales through implementation. We combine deep machine learning expertise with strong customer engagement, operating like startup CTOs who own end-to-end project execution.\nBy joining this team, you will drive the adoption of Mistral’s products, helping customers deploy AI solutions that deliver measurable business impact across industries.\n\nWhat You Will Do\n\n• \nDeploy production-ready AI use cases with significant business impact across diverse industries.\n• \nDevelop state-of-the-art GenAI applications, from consumer products to industrial solutions, driving technological transformation for customers.\n• \nCollaborate with researchers, AI engineers, and product teams on complex customer projects involving fine-tuning, advanced LLM applications, and contributions to open-source codebases.\n• \nParticipate in pre-sales calls to understand client needs, challenges, and aspirations, providing technical guidance on Mistral’s products.\n• \nWork with product and science teams to continuously improve model and product capabilities based on customer feedback.\n\nWhat We're Looking For\n\n• \nFluency in English.\n• \nExperience as a technical individual contributor (data scientist or software engineer) on AI-based products.\n• \nProven track record in implementing AI or machine learning products with APIs, back-end, and front-end interfaces.\n• \nHands-on experience with fine-tuning LLMs, advanced RAG, or agentic use cases.\n• \nDeep understanding of machine learning and LLM concepts and algorithms.\n• \nStrong technical coding skills in Python.\n• \nAbility to explain complex technical concepts clearly to both technical and non-technical audiences.\n• \nContributions to open-source projects, particularly in the LLM space.\n\nWhat We Offer\nWe offer a comprehensive benefits package designed to support your well-being, growth, and work-life balance. Benefits vary by country and may include healthcare coverage, parental leave, retirement plans, relocation support, wellness programs, meal and transportation allowances, and other location-specific perks.\nFor the most up-to-date details on benefits available in your location, please refer to our Benefits page.\n\nPrivacy Policy\nYour privacy matters to us. You can learn more about how we handle your personal data in our Applicant Privacy Policy.","source_board":"freehire:ashby","source_external_id":"applied-ai-engineer-australia-mistral-ai-v3cqc3v3","source_url":"https://jobs.ashbyhq.com/mistral.ai/ece48460-4c38-4f0e-880d-7dae96b2ad7d","source_posted_at":"2026-09-10T02:42:58Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"3b4f231e-4b43-577e-9b34-73ca8ea02486","company_id":"73ea83ec-c3d3-5c70-8961-0b239714c24e","title":"AI Engineer","location":"Perth WA","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"We're partnering with a leading enterprise embarking on a significant AI transformation initiative.\n\nAs part of a newly established operating model, we're seeking multiple AI Solutions Engineers to work directly with business units, identify high-value opportunities and deliver practical AI-enabled outcomes.\n\nThis is not a traditional AI engineering role. You'll operate in a Forward Deployed Engineering style environment, combining stakeholder engagement, solution design and hands-on development to drive tangible business value.\n\nWorking closely with business leaders, you'll help shape use cases, select the right technologies and build solutions ranging from low-code automation through to sophisticated GenAI and agentic AI applications.\n\nKey Responsibilities \n\n• Partner with business stakeholders to understand challenges and identify AI opportunities \n• Design and deliver AI-enabled solutions aligned to business outcomes \n• Develop GenAI, automation and agentic AI capabilities using modern cloud platforms \n• Build proof-of-concepts and production-ready solutions \n• Translate complex business requirements into scalable technical solutions \n• Evaluate and utilise the most appropriate tools for each use case, from low-code/no-code through to custom development \n• Contribute to establishing best practices, frameworks and repeatable delivery patterns \n• Collaborate closely with AI engineers, data scientists and technical leaders About You\n\nYou will bring a blend of technical capability and commercial awareness, with the ability to engage stakeholders while remaining hands-on.\n\nIdeally you'll have experience with:\n\n• Strong software engineering background, preferably Python \n• Experience delivering GenAI or LLM-based solutions \n• AI orchestration, automation or agentic workflow development \n• Cloud platforms such as AWS, Azure or GCP \n• Solution design and business-facing stakeholder engagement \n• End-to-end delivery experience from ideation through to production \n• Strong communication and consulting skills Nice to Have \n\n• Amazon Bedrock experience \n• LangChain, LangGraph or similar frameworks \n• RAG implementation experience \n• AI governance, adoption or enablement experience \n• Exposure to low-code/no-code automation platforms What's on Offer \n\n• Opportunity to help shape a new AI capability from the ground up \n• Work on genuine business-critical AI initiatives \n• Direct engagement with senior business stakeholders \n• High-impact environment focused on outcomes rather than experimentation \n• Collaborative team of AI engineers, data scientists and technical leaders If you're passionate about applying AI to solve real business problems and enjoy working at the intersection of technology and stakeholder engagement, we'd love to hear from you.","source_board":"freehire:seek","source_external_id":"ai-engineer-launch-recruitment-ztnbq7m6","source_url":"https://www.seek.com.au/job/94490024","source_posted_at":"2026-09-08T05:55:10Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"72dc87f1-e941-5c8f-8c93-06baf377f1f5","company_id":"f426cf75-1ef7-567a-a4e2-e69a4d916f54","title":"Forward-Deployed AI Engineer, Justice and Community Safety","location":"Melbourne","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About Maincode \nMaincode makes Matilda, an Australian-made AI stack we own end to end, from tin to token. We own and operate our own infrastructure here in Australia, we train and maintain our own frontier models, and we run multiple surfaces on top of them, including chat, coding and API. Everything we ship is built on capability we control ourselves.\nWe are hiring someone who cares about that. You should be passionate about Australian-made AI, a builder first, and keen to work directly with customers to help them move forward on the Matilda stack.\nThe Role \nYou will be Maincode's senior technical presence with customers in Melbourne, including departments across the Justice and Community Safety (JACS) portfolio.\nThis is a forward-deployed engineering role. You will embed with customer teams, get to grips with their hardest data problems, and design, adapt and deploy the Matilda stack to solve them. You will be the technical face of Maincode in the Justice and Emergency Services (J&ES) community: credible in a room of senior technical staff, able to prototype in days, and rigorous enough to ship working systems into classified environments.\nWhat You Will Do\n\n• \nEmbed with Victorian J&ES customers to find where Matilda can deliver real mission outcomes, and turn loosely defined requirements into concrete technical plans.\n• \nDesign, fine-tune, evaluate and deploy systems on the Matilda stack against customer data, including in on-premises, air-gapped and classified environments.\n• \nOwn delivery end to end, from data pipelines and fine-tuning through retrieval-augmented generation, evaluation, MLOps and hardening to relevant Government security standards.\n• \nBrief confidently at every level, from working engineers through to executives, and write architecture papers and evaluation reports that stand up to scrutiny.\n• \nBring what you learn in the field back to the team that trains the models, so customer experience directly shapes the next version of the stack.\nWhat You Will Bring\nEssential\n\n• \nMust hold an active AGSVA NV1 (or higher) security clearance and be willing to undergo Victoria Police organizational suitability vetting.\n• \nDeep hands-on experience in data science and ML engineering, with strong Python, modern ML stacks such as PyTorch, JAX and the Hugging Face ecosystem, and solid software engineering fundamentals.\n• \nDemonstrated experience deploying ML systems in secure government, defence or intelligence environments, including on-premises and air-gapped infrastructure.\n• \nWorking knowledge of the Victorian Protective Data Security Framework (VPDSF), the ISM, the Protective Security Policy Framework (PSPF), and data classification and handling requirements.\n• \nExcellent judgement and discretion, and the ability to operate autonomously inside customer environments.\n• \nThe ability to explain complex ML concepts crisply, and to write exceptionally well.\nHighly Regarded\n\n• \nPrior experience within State Law Enforcement, Public Safety, or Federal Intelligence (e.g., VicPol, ASIO, ASD, or Defence S&T), ideally in a data science, technical, or analytic role.\n• \nHands-on experience with large language models: fine-tuning, evaluation, retrieval-augmented generation, and their known failure modes.\n• \nFamiliarity with intelligence-adjacent data workflows such as entity resolution, geospatial analysis, OSINT, graph analytics, or tradecraft tooling.\n• \nSolutions architecture or technical pre-sales experience in a commercial setting.\nEligibility \nThis position requires an active AGSVA NV1 (or higher) clearance. Due to clearance eligibility requirements, applicants must be Australian citizens. You will be required to consent to AGSVA revalidation, and to obtain and maintain customer-specific briefings and accesses as required.\nDetails\n\n• \nLocation: Melbourne, VIC. Regular work from customer facilities and secure sites, with some work from Maincode offices.\n• \nType: Full-time, permanent.\n• \nRemuneration: Negotiable based on experience, plus super and equity.\nWho Thrives Here \nBuilders who want to spend time with customers, and customer people who actually build. If you care about Australian-made AI and you would rather spend your week deploying systems with agencies than talking about them, you will do well here.","source_board":"freehire:ashby","source_external_id":"forward-deployed-ai-engineer-justice-and-community-safety-maincode-7firf4of","source_url":"https://jobs.ashbyhq.com/maincode/086f2289-046b-4c6c-93c5-ffcaed88d4bc","source_posted_at":"2026-09-07T05:39:29Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"3e3a9d6c-1487-5ee3-b117-921710c6fcfa","company_id":"662864bf-f93b-5144-bf28-11edb95173e2","title":"AI Engineer / Software Integrator","location":"Eastwood, Sydney NSW","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About Us\nNew Home Care is an innovative, rapidly growing Aged Care and NDIS provider based in Eastwood, Sydney. We pride ourselves on delivering exceptional, compliant, and deeply personalized care to older Australians. As the industry evolves, we are actively leveraging cutting-edge technology and artificial intelligence to streamline our operations, automate administrative workflows, and empower our team to focus entirely on what matters most: our clients.\nRole Overview\nWe are seeking an agile, sharp, and highly practical AI Engineer / Software Integrator to join our team. Unlike rigid corporate roles, this position offers high autonomy and the chance to make an immediate impact.\nYour mission will be two-fold: quickly master and map out the software systems and processes we currently use, and then design and deploy smart AI programs that sit on top of them. You will be directly responsible for bringing cutting-edge AI capabilities—such as Claude’s Model Context Protocol (MCP)—into the real-world operational environment of home aged care.\nKey Responsibilities\n\n• \nRapid System Onboarding: Quickly learn, reverse-engineer, and document the workflows of all software systems currently developed and utilized by New Home Care.\n• \nAged Care AI Application: Identify operational bottlenecks (e.g., document processing, scheduling optimization, client address updates, or compliance tracking) and build AI tools or scripts to solve them.\n• \nReal-World MCP Implementation: Design and implement production-ready AI tools utilizing Claude’s Model Context Protocol (MCP) and other modern orchestration frameworks to securely connect LLMs with our local data sources and existing software ecosystems.\n• \nBridge the Gap: Create seamless, automated pipelines that complement our primary software platforms without disrupting daily care operations.\nWhat You’ll Bring (Requirements)\n\n• \nFast-Learner Mindset: A proven track record of entering an unfamiliar software environment and mastering its structure, APIs, and data flows quickly without extensive hand-holding.\n• \nPractical AI/ML Programming Experience: Hands-on experience developing actual, deployed AI applications. You know how to move beyond basic API prompts to build functional, resilient tools.\n• \nCutting-Edge Protocol Knowledge: Deep familiarity or direct experience with Claude MCP (Model Context Protocol) or similar context-sharing protocols, demonstrating you know how to build secure, bidirectional connections between AI models and local databases/development environments.\n• \nAged Care Empathy: An understanding of (or a strong willingness to learn) the compliance, privacy, and operational nuances of the Australian Aged Care and NDIS sectors.\n• \nCore Tech Stack: Strong proficiency in Python or TypeScript/Node.js. Experience with API integration, secure data handling, and lightweight automation scripting.\nWhy Join New Home Care?\n\n• \nDirect Impact: You aren't a cog in a massive corporate machine. Your code and AI tools will directly improve the lives of care workers and elderly clients.\n• \nTrue Innovation: Work directly with leadership to pioneer real-world AI applications (like MCP) that most traditional companies are only talking about.\n• \nConvenient Location: Based in the vibrant Eastwood area with a flexible, supportive team culture.","source_board":"freehire:seek","source_external_id":"ai-engineer-software-integrator-new-home-care-ttayw7c6","source_url":"https://www.seek.com.au/job/94427773","source_posted_at":"2026-09-04T09:21:33Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"d55f04ef-c7eb-539f-99fa-892c317d6207","company_id":"91074b5f-ad29-5caf-a17d-c9b35ec45d13","title":"AI Engineer","location":"Geelong, South West Coast VIC","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"AI Engineer\n\n• X2 Full time, fixed term roles until 30 June 2027\n\n• Geelong office location, with flexible hybrid working\n\n• Offering a competitive starting base salary of $136,500 plus super and benefits\n\nCare in Action\nWith a career at the TAC, you’ll be helping us look out for the lives of everyone who travels on Victoria’s roads. That’s care in action.\n\nFind out more about our shared purpose, and what drives every one of us.\n\nRight now, we’re seeking two AI Engineers who will play their part in this shared purpose, while also supporting the progress of clients and colleagues so they can achieve great things. That’s truly rewarding work that will help us continue to deliver life-critical services where it matters. \n\nAbout the role\nAs an AI Engineer, you’ll design, build and support production‑grade AI applications and solutions that help TAC teams improve services, decision‑making and operational efficiency. A major focus of this role will be delivering AI capabilities, using techniques such as retrieval‑augmented generation, context engineering, prompt orchestration and modern application frameworks to turn complex information into clear, usable insights.\n\nYou’ll also develop and maintain data pipelines, deployment pipelines, and MLOps/AIOps practices to ensure TAC’s AI solutions are reliable, observable and secure in production environments. This is a hands‑on engineering role suited to someone who has moved real AI solutions into production, thrives in an agile, collaborative environment, and brings a strong engineering mindset rather than a data science focus.\n\nAbout the Team\nThis role sits within the Performance, Insights and Analytics team in the broader Performance, Risk & Strategy division, working closely with data professionals, product owners and security teams to deliver high‑value AI solutions.\n\nYou’ll be supported by a manager who values clarity, autonomy and technical excellence, and you’ll collaborate with a team known for being curious, adaptable and committed to making the complicated simple.\n\nWhat we’re looking for\n\nHands‑on AI engineering expertise\nYou have practical experience delivering production‑grade AI solutions, including generative AI techniques such as retrieval‑augmented generation, context engineering and prompt orchestration. You’ve built and deployed real AI applications, ideally in areas like RAG and document content extraction and summarisation, with a strong focus on reliability and maintainability.\n\nStrong software and cloud engineering capability\nYou bring proficiency in Python and SQL, and experience building AI‑enabled applications using modern frameworks. You’re comfortable working with Azure AI Services, Databricks and contemporary engineering practices to deliver secure, scalable solutions.\n\nMLOps, AIOps and DevOps mindset\nYou apply DevOps principles including source control, automated testing, CI/CD pipelines and infra‑as‑code. You have experience with monitoring, logging, alerting and observability for AI applications, ensuring solutions perform reliably in production environments.\n\nAdaptable, collaborative and delivery‑focused\nYou thrive in an agile environment, iterate quickly and communicate clearly. You work autonomously with strong ownership, while collaborating effectively with multidisciplinary teams to solve problems and deliver high‑quality outcomes.\n\nWhy you’ll love it here\nThere’s more to work than a competitive salary and amazing employee benefits. As our newest AI Engineer, you’ll also:\n\nMake a positive difference\nEvery day the work you do at the TAC contributes to something bigger. As part of an inclusive, supportive team you’ll find real purpose in achieving goals, together.\n\nBe rewarded for great work\nWe value our people, offering a service delivery payment, salary packaging and a reward and recognition program.\n\nGrow and go places\nWe’re invested in your progress. When you work for one of Victoria’s largest and leading workplaces, you’ll receive extensive internal opportunities for development and access to the LinkedIn Learning Digital Hub.\n\nReady to put care in action? We’d like to hear from you.\nClick apply to submit your Cover Letter and Resume. If successful, you’ll progress to an interview. All applicants will be advised of the outcome of their application.\n\nFor more information, read the attached Position Description or contact Shay McLean at Shay_Mclean@tac.vic.gov.au for a confidential discussion. Applications for this role will be accepted up until 11:55pm on Monday 7 September 2026.\n\nIf we can do anything to help make applying for this role easier, or you have an adjustment request, please let our Talent Acquisition Team know at recruitment@tac.vic.gov.au. If over the phone is better for you, our number is 03 9300 0501.\n\nA safe place to work\nWe’re committed to the health, safety and wellbeing of employees. This extends to inclusion, diversity and accessibility in our employment practices, and encourage Aboriginal and Torres Strait Islander people, people with disability, men, women and gender diverse people, culturally diverse, and LGBTIQA+ people to apply for roles.\n\nChild Safety\nAt the TAC we are committed to the safety of children and young people. For more information regarding our commitment to child safety, please visit our website. \n\nPosition Description_AI Engineer.pdf","source_board":"freehire:seek","source_external_id":"ai-engineer-transport-accident-commission-victoria-bwa6wqt2","source_url":"https://www.seek.com.au/job/94348861","source_posted_at":"2026-09-01T23:14:15Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"0672c7f6-eda7-55ac-a3b7-b7cfd7554f28","company_id":"f426cf75-1ef7-567a-a4e2-e69a4d916f54","title":"Forward-Deployed AI Engineer, Government and National Security","location":"Canberra","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About Maincode\nMaincode makes Matilda, an Australian-made AI stack we own end to end, from tin to token. We own and operate our own infrastructure here in Australia, we train and maintain our own frontier models, and we run multiple surfaces on top of them, including chat, coding and API. Everything we ship is built on capability we control ourselves.\nWe are hiring someone who cares about that. You should be passionate about Australian-made AI, a builder first, and keen to work directly with customers to help them move forward on the Matilda stack.\n\nThe role\nYou will be Maincode's senior technical presence with customers in Canberra, including departments such as DFAT and agencies across the National Intelligence Community (NIC).\nThis is a forward-deployed engineering role. You will embed with customer teams, get to grips with their hardest data problems, and design, adapt and deploy the Matilda stack to solve them. You will be the technical face of Maincode in the national security community: credible in a room of senior technical staff, able to prototype in days, and rigorous enough to ship working systems into classified environments.\n\nWhat you will do\n\n• \nEmbed with government and NIC customers to find where Matilda can deliver real mission outcomes, and turn loosely defined requirements into concrete technical plans.\n• \nDesign, fine-tune, evaluate and deploy systems on the Matilda stack against customer data, including in on-premises, air-gapped and classified environments.\n• \nOwn delivery end to end, from data pipelines and fine-tuning through retrieval-augmented generation, evaluation, MLOps and hardening to Australian Government security standards (ISM, PSPF, Essential Eight).\n• \nBrief confidently at every level, from working engineers through to SES, and write architecture papers and evaluation reports that stand up to scrutiny.\n• \nBring what you learn in the field back to the team that trains the models, so customer experience directly shapes the next version of the stack.\n\nWhat you will bring\nEssential\n\n• \nAn active Top Secret Positive Vetting (TSPV) clearance, with the ability to transfer sponsorship and consent to AGSVA revalidation.\n• \nDeep hands-on experience in data science and ML engineering, with strong Python, modern ML stacks such as PyTorch, JAX and the Hugging Face ecosystem, and solid software engineering fundamentals.\n• \nDemonstrated experience deploying ML systems in secure government, defence or intelligence environments, including on-premises and air-gapped infrastructure.\n• \nWorking knowledge of the ISM, the Protective Security Policy Framework, and data classification and handling requirements.\n• \nExcellent judgement and discretion, and the ability to operate autonomously inside customer environments.\n• \nThe ability to explain complex ML concepts crisply, and to write exceptionally well.\nHighly regarded\n\n• \nPrior experience within the National Intelligence Community, for example ASD, ASIO, ASIS, ONI, DIO or AGO, or in Defence S&T, ideally in a data science, technical or analytic role.\n• \nHands-on experience with large language models: fine-tuning, evaluation, retrieval-augmented generation, and their known failure modes.\n• \nFamiliarity with intelligence-adjacent data workflows such as entity resolution, geospatial analysis, OSINT, graph analytics, or tradecraft tooling.\n• \nSolutions architecture or technical pre-sales experience in a commercial setting.\n\nEligibility\n\n• \nThis position requires an active TSPV clearance. Due to clearance eligibility requirements, applicants must be Australian citizens.\n• \nYou will be required to consent to AGSVA revalidation, and to obtain and maintain customer-specific briefings and accesses as required.\n\nDetails\n\n• \nLocation: Canberra, ACT. Regular work from customer facilities and secure sites, with some work from Maincode offices.\n• \nType: Full-time, permanent.\n• \nRemuneration: Negotiable based on experience, plus super and equity.\n\nWho thrives here\nBuilders who want to spend time with customers, and customer people who actually build. If you care about Australian-made AI and you would rather spend your week deploying systems with agencies than talking about them, you will do well here.","source_board":"freehire:ashby","source_external_id":"forward-deployed-ai-engineer-government-and-national-security-maincode-kc5indqy","source_url":"https://jobs.ashbyhq.com/maincode/c529cab5-4bdd-43f2-bd18-b4c77bdf8fdd","source_posted_at":"2026-09-01T03:26:39Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"7b8609ac-807e-5c18-bbd2-d161e45f58f5","company_id":"776663aa-907b-5d4d-93d2-e6885c299fc9","title":"AI Engineer","location":"Melbourne, VIC, au","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"The Global Data - AI team sits within BlueScope's Enterprise Technology, Data & Analytics function and is responsible for advancing the organisation's AI capability and helping unlock value through safe, scalable and responsible adoption of artificial intelligence. The team partners closely with business leaders and technical specialists to deliver AI solutions that improve decision-making, productivity and customer and employee experiences across BlueScope's global operations. \nWe are seeking an AI Engineer to design, develop and deploy enterprise AI solutions that deliver measurable business outcomes. Reporting to the Global Lead Advanced Analytics, you will play a key role in building production-grade AI products, Generative AI solutions, Retrieval Augmented Generation (RAG) systems, agentic workflows, computer vision capabilities and reusable AI platform components that help shape BlueScope's future. \nThis is a hands-on technical engineering role for someone who can design, build, integrate, deploy and support production AI systems. It is not a business-user, AI adoption, prompt engineering or productivity-copilot role focused primarily on using off-the-shelf AI tools. \nThis role can be based in Melbourne (CBD) or Sydney (Mascot). \nKey Responsibilities \nAs an AI Engineer, you will work at the forefront of AI innovation, developing practical solutions that solve real business challenges across BlueScope. You will collaborate with business stakeholders, data scientists, data engineers, architects, cybersecurity and platform teams to translate opportunities into trusted, scalable AI products and reusable enterprise AI capabilities. \nResponsibilities include: \n\n• \nDesign, develop and support production-grade AI applications, assistants, copilots and intelligent services. \n\n• \nBuild and enhance enterprise Generative AI capabilities, including RAG and agentic AI solutions. \n\n• \nDevelop scalable AI products that improve operational performance, productivity and decision-making. \n\n• \nOwn and enhance reusable AI platform components, frameworks, engineering standards, templates and best practices that enable teams to build AI solutions safely and consistently. \n\n• \nSupport the development of computer vision solutions for operational and manufacturing use cases. \n\n• \nPartner with stakeholders to identify, prioritise and deliver high-value AI opportunities. \n\n• \nIntegrate AI solutions with enterprise systems, platforms and business workflows. \n\n• \nEnsure AI solutions are secure, maintainable, scalable and aligned to responsible AI principles. \n\n• \nImplement secure enterprise integration patterns, including access controls, environment separation, identity, data permissions, model access governance and collaboration with cloud, cybersecurity and platform teams. \n\n• \nBuild production-grade RAG and GenAI patterns, including ingestion, indexing, retrieval quality, evaluation, observability, feedback loops, cost awareness and lifecycle support. \n\n• \nContribute to technical product ownership for AI platforms and products, including requirements shaping, roadmap input, adoption support, technical documentation and engagement with internal teams and external technology partners. \nYou are a hands-on software engineer who enjoys solving complex problems and building innovative technology solutions that create tangible business value. You combine strong software engineering discipline, cloud platform experience and practical AI capability with a delivery mindset focused on production outcomes. \nYou will bring: \n\n• \nA degree in Computer Science, Software Engineering, Data Science, Information Technology or a related discipline. \n\n• \nDemonstrated experience in software engineering, AI engineering, platform engineering or a related technical field, with accountability for building and supporting production systems. \n\n• \nStrong Python development skills and experience building production-grade applications, APIs, services or reusable engineering components. \n\n• \nExperience applying AI, machine learning or Generative AI technologies to solve business challenges. \n\n• \nDepth in technical delivery beyond the use of AI productivity tools, including the ability to design, implement, test, deploy, monitor and improve AI-enabled software products. \n\n• \nExperience designing, developing and deploying enterprise applications or digital products. \n\n• \nStrong analytical, problem-solving and stakeholder engagement skills. \n\n• \nThe ability to work effectively within multidisciplinary teams and influence outcomes through collaboration. \nYou will also bring experience working with modern AI engineering tools and platforms, enabling you to build, deploy, secure and scale enterprise AI solutions in a production-ready environment. \n\n• \nExperience with Azure and Databricks platforms. \n\n• \nExperience using AI engineering frameworks such as LangChain, LlamaIndex or similar technologies. \n\n• \nKnowledge of MLOps, DevOps and modern software delivery practices that support the deployment and management of enterprise AI solutions \n\n• \nExperience with secure cloud integration patterns, identity and access management, CI/CD, observability, testing and operational support for AI-enabled applications. \nThe BlueScope Difference \nA career at BlueScope provides the opportunity to make a difference - to you, to your team, to our customers, to transforming products, processes and brands, and to an organisation intent on shaping a better built environment for all our communities. At BlueScope, you will: \n\n• \nMake an impact both within the organisation and in the broader community. \n\n• \nCreate and deliver innovative products and solutions that shape the world we live in. \n\n• \nGrow on a path of continuous learning and development. \n\n• \nEnjoy the sense of belonging that comes from working with people who genuinely look out for one another. \nWe're dedicated to supporting our people, rewarding successes and helping individuals grow. We foster workplace flexibility and an inclusive environment that welcomes people of all backgrounds. Together we are committed to Our Purpose: Creating Strength.","source_board":"freehire:smartrecruiters","source_external_id":"ai-engineer-bluescope-khs6syu5","source_url":"https://jobs.smartrecruiters.com/BlueScope/744000146609569-ai-engineer","source_posted_at":"2026-09-01T03:11:10Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"2caf0bdd-8ab7-551e-a6fc-ba420f6eb4eb","company_id":"f40e87a4-61f9-5390-806e-6a33f9bb3899","title":"iOS Developer - AI Finance Agent","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About Doit\nWe are focused on reinventing how people spend, save, invest, exchange, travel, and more. Our objective is to build tools that will help people get more from their money and become an expert at ease. We believe AI will help make finance smart, assessible and safe. \n\nWe are looking for the most talented and driven people we can find. We are looking for people who work for their passion, not counting hours. Who loves building great next-generation products, not status quo. Who cares about redefining how everyone around us can get the best financial applications, not for an exclusive few. We have teams working around the world, with over 20 nationalities and growing from our offices and remotely. Join us and build a better future for our society. \n\nIn 2019, we built the first mobile-first, insurance platform, enabling insurance to be accessible online by millions in the region. Today, it's the leading insurance platform in Southeast Asia.\n\nThe Role\nWe are looking for iOS engineers to build the native iOS experience for Doit's AI Finance Agent.\n\nThis role is for someone who cares about clean user flows, fast performance, product quality and shipping reliable mobile features used by real customers.\n\nWhat Will You Build\n\n• \nBuild and ship native iOS features for onboarding, accounts, cards, payments, transfers, rewards and AI-assisted user journeys.\n• \nMake complex financial flows feel clean, fast and simple on mobile.\n• \nWork with product, design, backend and AI engineers to take ideas from rough concept to production release.\n• \nOwn app quality across performance, crash rate, loading states, edge cases, responsiveness and release stability.\n• \nUse production feedback, analytics and customer behaviour to improve features after launch.\n• \nIntegrate APIs, authentication, secure data handling and financial workflows with strong attention to reliability.\n\nWhat We're Looking For\n\n• \nStrong native iOS experience using Swift.\n• \nExperience shipping iOS apps used by real users.\n• \nGood understanding of SwiftUI, UIKit, async/await and iOS architecture patterns.\n• \nStrong product sense and care for UX, not just building screens.\n• \nAble to debug production issues and improve performance, reliability and app quality.\n• \nComfortable working with ambiguity and moving fast without lowering the bar.\n\nThe Bar\nWe are looking for engineers with real technology career highlights. A strong highlight is not just working at a famous company. A strong highlight means you personally helped build, ship or scale a serious product, platform or system.\n\nThis Role Is Not For\n\n• \nEngineers who only want fully defined tickets.\n• \nDevelopers who build screens without caring about user experience.\n• \nPeople who ignore crashes, edge cases, loading states or performance.\n• \nEngineers who move slowly in a startup environment.\n• \nPeople who exaggerate impact without explaining their actual contribution.\n\nLocation\nThis role is remote, but candidates must be based in Australia. We are hiring specifically for this market, so applicants should already be based in Australia.\n\nLanguage\nEnglish is our main working language across global teams. Strong English communication is required.\n\nInterview Process\nOur process is designed to move fast:\n1. Online assessment or practical task\n2. Role-specific interview\n3. CEO / final round\n\nFor strong candidates, we aim to complete the process and make an offer within 1 week from the start of the interview process. Candidates who complete assessments quickly will be prioritized.","source_board":"freehire:ashby","source_external_id":"ios-developer-ai-finance-agent-bjakcareer-dapnqtyj","source_url":"https://jobs.ashbyhq.com/bjakcareer/2280113b-072b-4950-a02a-2e2d2eba890a","source_posted_at":"2026-09-01T03:51:53Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"cebb2c18-f059-533e-8aa6-215aa85fc23b","company_id":"74f244dc-3cc6-593b-9e3d-960009bc986b","title":"AI Engineer | Agent Engineer (Agentic AI)","location":"Sydney","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Line of ServiceAdvisory\n\nIndustry/SectorTechnology\n\nSpecialismAdvisory - Other\n\nManagement LevelSenior Associate\n\nJob Description & SummaryThe AI team is comprised of highly experienced designers, developers, engineers, data scientists and analysts who are responsible for delivering digital products and AI solutions to PwC's business across multiple lines of service in Australia. \n\nWe partner with subject matter experts across the business to advise on, design and build agentic AI systems and LLM-powered products that transform the way we deliver assurance, advisory, tax and legal services to our clients. \n\nAs an AI Engineer on our team, you will design, build and evaluate production agent systems: agents that reason, call tools, retrieve knowledge, manage their own context and complete long-horizon, multi-step tasks on behalf of our practitioners and clients. Our agent harness is built in TypeScript on the Vercel AI SDK, with model and provider routing handled through a LiteLLM-based gateway, and it runs at scale in the Azure cloud. You will own problems end to end: from framing the approach and prototyping, to shipping reliable, observable agents in production. \n\nWe are an evaluation-led team, so we care deeply about rigour: measuring agent quality, running evaluations, and using the scientific method to know whether something actually works, not just whether it demos well.\n\nWhy PwC? \n\nAt PwC Australia, your skills meet purpose. We tackle big challenges across industries like finance, technology, energy, and health —giving you the chance to make a real impact. Here, your growth is our priority. You’ll work with leading teams, explore new technologies, and unlock your full potential. \n\nJoin a global community of more than 370,000 people who value bold ideas, collaboration, and lasting change. Together, we’re building trust and shaping the future.\n\nWhat you’ll do: \n\n• \n\n• \nBuild and extend our agent harness in TypeScript: the runtime loop, tool dispatch, streaming, retries and tool-call repair, state persistence and recovery, and the guardrails that keep agents reliable and on-budget. \n\n• \nDesign context and memory strategies for long-horizon work: context compaction and summarisation, working versus long-term memory, prompt and response caching, cache-aware prompt construction, and token budgeting across multi-step runs. \n\n• \nArchitect multi-agent and sub-agent systems: lead and worker patterns, task decomposition, parallel sub-agent execution, hand-off and delegation contracts, shared state, and result aggregation back to a lead agent. \n\n• \nDesign and expand agent tool ecosystems with well-typed, testable schemas: a sandboxed command tool giving agents a real filesystem and shell, file and document operations, code execution, web search, and connectors that surface enterprise and client data sources (for example MS Graph, SharePoint, Outlook and Teams) to agents as tools. \n\n• \nRoute across multiple models and providers through our LiteLLM-based gateway, tuning model selection, fallbacks and routing policy for quality, latency and cost - including the use of small language models for narrow, high-volume or latency-sensitive steps. \n\n• \nEngineer retrieval and RAG pipelines that ground agent outputs in trusted sources: chunking, embeddings, vector search on PostgreSQL with pgvector, hybrid and re-ranked retrieval, and retrieval exposed to agents as tools. \n\n• \nProduce structured, reliable model outputs using typed schemas (for example Zod with the Vercel AI SDK) and design robust prompts, system instructions and agent skills. \n\n• \nBuild evaluation harnesses and offline batch evals, including deep-research style runs and trajectory-level assessment of tool use, to measure accuracy, faithfulness, cost and latency - and use those signals to iterate. \n\n• \nInstrument agents with observability and tracing (for example Langfuse, OpenTelemetry) and track token usage, cache hit rates and cost in production. \n\n• \nProduce clean, maintainable, efficient code deployed at scale in the Azure cloud; scaffold new projects, pair with engineers, and review pull requests. \n\n• \nContribute to team stand-ups and the broader software development lifecycle, and participate in firmwide AI and engineering forums. \n\nWhat we’re looking for: Applicants must be able to demonstrate the following key capabilities. We do not expect every box ticked, strong fundamentals and a track record of shipping LLM-powered products matter most. \n\nCore skills: \n\n• \n\n• \nStrong TypeScript development experience, ideally in a Node.js backend context, with confident use of the type system to model tool schemas, agent state and structured outputs. \n\n• \nHands-on experience building agents with a modern agent framework or SDK, with the Vercel AI SDK strongly preferred (streaming, tool calling, structured generation, provider abstraction). \n\n• \nDemonstrated experience building or operating an agent harness or runtime loop in production: tool dispatch, error handling and tool-call repair, interrupt and resume, and long-running task execution. \n\n• \nPractical understanding of context engineering: context window management and compaction, memory design, prompt and response caching, and cost/latency trade-offs across a multi-step run. \n\n• \nExperience designing multi-agent architectures, including sub-agent orchestration, delegation boundaries, shared state and failure handling. \n\n• \nDeep, practical knowledge of prompt engineering, agentic patterns, tool and function calling, and structured outputs. \n\n• \nExperience routing across multiple models and providers through a gateway such as LiteLLM, and reasoning clearly about model selection trade-offs. \n\n• \nExperience building and optimising RAG and retrieval pipelines, including their evaluation, with industry-standard tooling. \n\n• \nStrong experience with PostgreSQL, including pgvector for embeddings and hybrid or semantic search, and using Postgres as the durable store for agent state, memory and traces. \n\n• \nAn evaluation-first mindset: designing evals for agent behaviour, and using evidence rather than demos to reach defensible conclusions about quality. \n\n• \nStrong critical thinking, analytical rigour and outstanding attention to detail. \n\n• \nProper source code management and confident use of Git, and comfort working in a large shared monorepo (for example Nx or Yarn workspaces) with project boundaries and shared libraries. \n\n• \nGood written and verbal communication, and the ability to work effectively with remote teams. \n\n• \nA proactive, problem-solving approach and the ability to solve complex problems as part of a team. \n\nDesirable skills: \n\n• \n\n• \nExperience with small language models (SLMs): selecting, fine-tuning, distilling, quantising or self-hosting smaller models, and using them for routing, classification, extraction or guardrail steps within a larger agent system. \n\n• \nExperience with LLM observability and cost/quality tracing (for example Langfuse, OpenTelemetry). \n\n• \nExperience designing sandboxed execution environments for agents: containerised or virtualised sandboxes, shell and filesystem access exposed as a command tool, isolation and resource limits, and safe tool surface design. Familiarity with emerging tool-interoperability standards such as MCP is a plus. \n\n• \nExperience building connectors and integrations to enterprise systems and data sources, including authentication, permissioning, incremental sync and rate-limit handling. \n\n• \nFull-stack TypeScript experience (NestJS, Next.js / React) with either tRPC or GraphQL / Apollo including code generation, and building interfaces for agent products such as streaming and human-in-the-loop review. \n\n• \nExperience with computer-use or browser-automation agents (for example Playwright). \n\n• \nExperience with document generation pipelines (DOCX, PPTX, PDF) or rich-text editor frameworks such as Lexical, ideally over a real-time collaborative layer (Yjs / Hocuspocus or equivalent CRDT tooling). \n\n• \nWorking Python capability, including building and running production services (for example FastAPI) as well as evaluation, data work and model experimentation; comfort moving across the TypeScript and Python stack is valued. \n\n• \nA research background in ML or LLM development, and the ability to identify emerging techniques and apply them to practical situations. \n\n• \nKnowledge of classical ML and deep learning, preferably in NLP. \n\n• \nExperience with well-structured backend services at scale: microservices and containerisation (Docker), and ideally domain-driven and event-driven patterns such as domain / application / infrastructure layering, repositories and domain events. \n\n• \nExperience with durable job queues and background processing for long-running agent workloads (for example BullMQ on Redis, Azure Service Bus), and with Redis for caching, locks and shared state. \n\n• \nExperience developing on cloud environments, particularly Azure (Azure OpenAI, AI Search, Blob, Key Vault, App Insights). \n\n• \nKnowledge of agile software development lifecycles (SDLC), and exposure to CI/CD pipelines (Azure DevOps, GitHub Actions) and infrastructure as code (Terraform). \n\nWhat you’ll gain: \n\n• \nThe opportunity to work with leading organisations and cutting-edge technology that challenge and expand your expertise. \n\n• \nWork within an inclusive environment committed to Inclusion and Diversity and First Nations Prosperity, ensuring diverse perspectives are at the forefront of our work. \n\n• \nFlexibility means trusting you to choose when, where, and how you work balancing what’s best for you, your team, and your clients to grow and thrive together. \n\n• \nClear paths for career progression supported by continuous learning and leadership development. \n\n• \nGenerous leave entitlements to support your work-life balance - including floating public holidays, birthday leave and ability to purchase additional leave on top of your four weeks. \n\n• \nA world-class parental leave policy offering up to 26 weeks of leave for caregivers, supporting your family and personal life. \n\nWe know that perks are as important as your financial rewards. Explore all the benefits that PwC has to offer here. \n\nReady to grow here and go further? Join PwC Australia as a [Job Title] and make an impact that goes beyond the expected. Apply now and take your next step with a team shaping the future. \n\nWe’re committed to treating all our job applicants fairly and with respect, irrespective of their actual or assumed background, disability, neurodivergence, or any other protected characteristic and to maintaining a safe, respectful workplace for everyone. We want you to have every opportunity to thrive in our selection process. In the application form, you can let us know what adjustments you require during our recruitment process and/or any workplace accommodations you anticipate needing to help you perform your role. \n\nNo agencies please: We kindly request that recruitment agencies do not submit CVs in response to this advertisement. We are only accepting applications directly from individuals. \n\nEducation (if blank, degree and/or field of study not specified)Degrees/Field of Study required:\n\nDegrees/Field of Study preferred:\n\nCertifications (if blank, certifications not specified)\n\nRequired SkillsAI Agents, Data Science\n\nOptional SkillsAccepting Feedback, Accepting Feedback, Active Listening, AI Implementation, Analytical Thinking, C++ Programming Language, Communication, Complex Data Analysis, Creativity, Data Analysis, Data Infrastructure, Data Integration, Data Modeling, Data Pipeline, Data Quality, Deep Learning, Embracing Change, Emotional Regulation, Empathy, GPU Programming, Inclusion, Intellectual Curiosity, Java (Programming Language), Learning Agility, Machine Learning {+ 25 more}\n\nDesired Languages (If blank, desired languages not specified)\n\nTravel RequirementsUp to 20%\n\nAvailable for Work Visa Sponsorship?Yes\n\nGovernment Clearance Required?No\n\nJob Posting End DateSeptember 30, 2026","source_board":"freehire:workday","source_external_id":"ai-engineer-agent-engineer-agentic-ai-pwc-xcyzn3ps","source_url":"https://pwc.wd3.myworkdayjobs.com/NonPublic_Postings/job/Sydney/Data-Scientist---LLM-Engineer---Senior-Associate-Manager_733066WD","source_posted_at":"2026-08-31T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"810aa7f2-4325-50d5-8926-2e8766422a7f","company_id":"3a7f8362-7999-5eec-9b5e-b06ccb9fc982","title":"Java AI Engineer","location":"Sydney - Client Location","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"We are seeking a highly skilled Java AI Engineer with strong expertise in Java, Spring Boot, and modern AI technologies, including Claude, OpenAI, Large Language Models (LLMs), Agentic AI, RAG, and AI-powered application development.\nThis role will be at the forefront of building next-generation intelligent applications by combining enterprise-grade Java engineering with cutting-edge AI capabilities. You will design, develop, and deploy scalable AI-enabled solutions that enhance business processes, automate workflows, and deliver exceptional user experiences.\nKey Responsibilities\n\n• Design, develop, and maintain scalable applications using Java, Spring Boot, and Microservices Architecture.\n• Build AI-powered enterprise applications leveraging Claude, OpenAI, and other LLM technologies.\n• Design and implement Retrieval-Augmented Generation (RAG) solutions using vector databases and enterprise knowledge sources.\n• Develop AI Agents capable of performing complex tasks, orchestration, reasoning, and workflow automation.\n• Integrate AI models and services into enterprise platforms through APIs and modern frameworks.\n• Collaborate with architects, product owners, and business stakeholders to identify and deliver AI-driven use cases.\n• Design secure, scalable, and resilient cloud-native solutions.\n• Participate in technical design discussions, code reviews, and architecture decisions.\n• Optimize performance, reliability, and scalability of AI-powered systems.\n• Stay current with emerging advancements in AI, LLMs, Agentic AI, and enterprise application development.\nS​YNECHRON’S DIVERSITY & INCLUSION STATEMENT\n\nDiversity & Inclusion are fundamental to our culture, and Synechron is proud to be an equal opportunity workplace and is an affirmative action employer. Our Diversity, Equity, and Inclusion (DEI) initiative ‘Same Difference’ is committed to fostering an inclusive culture – promoting equality, diversity and an environment that is respectful to all. We strongly believe that a diverse workforce helps build stronger, successful businesses as a global company. We encourage applicants from across diverse backgrounds, race, ethnicities, religion, age, marital status, gender, sexual orientations, or disabilities to apply. We empower our global workforce by offering flexible workplace arrangements, mentoring, internal mobility, learning and development programs, and more.\n\nAll employment decisions at Synechron are based on business needs, job requirements and individual qualifications, without regard to the applicant’s gender, gender identity, sexual orientation, race, ethnicity, disabled or veteran status, or any other characteristic protected by law.\n\nCandidate Application Notice","source_board":"freehire:workday","source_external_id":"java-ai-engineer-synechron-zf4ptmg5","source_url":"https://synechron.wd1.myworkdayjobs.com/SynechronCareers/job/Sydney---Client-Location/Java-AI-Engineer_JR1043235","source_posted_at":"2026-08-28T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"5c647a1e-9038-5bbb-bb62-05fa7ba284d6","company_id":"44ad501c-7072-56cb-b1c7-99f95dc18aff","title":"Software Engineer - Machine Learning","location":"Sydney, NSW","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"• Build innovative AI and machine learning products that shape how Australia experiences property.\n• Join a collaborative team where learning, experimentation and impact go hand in hand.\n• Permanent role based in Sydney\n\nWe're REA\nWith bold and ambitious goals, REA Group is changing the way the world experiences property. No matter where you're at on your property journey, we're here to help with every step - whether that's finding or financing your next home.\n\nOur people are the key to our success. At the heart of everything we do, is a thriving culture centred around high performance and care. We are purpose driven and collaborative, which drives innovation and our ability to make a real impact. As such, we’re proud to have been named one of Australia’s Best Workplaces four times since 2021 — including third place in 2025 — plus Best Workplace for Women in 2023 and Best Workplace in Technology in 2024 and 2025. These listings are testament to every person who helps make REA a great place to work.\n\nWhere the team fits in\nPropTrack is Australia’s leading source of property insights, digital valuation solutions, and predictive analytics. This role sits within our Data Science & Analytics team, which is responsible for the development, deployment, and operations of internal and customer-facing statistical, machine learning, and AI models. The team collaborates closely with a wide range of groups across the business, including Core Property Data, Mortgage Solutions, Consumer AI, Consumer Product & Experience, Commercial and Mortgage Choice. \n\nWhat the role is all about\n\n• Design, code, test, and deploy machine learning pipelines using Python, SQL, Infrastructure as Code (IaC), AWS, and GCP. \n\n• Build innovative AI products using Generative AI, LLMs, and traditional machine learning techniques. \n\n• Prototype and spike out Proofs of Concept (POCs) to explore new ideas and evaluate their feasibility in collaboration with senior engineers. \n\n• Support data processes - assist with ad-hoc analysis, automated dashboards, and self-service reporting tools so that everyone gets a good sense of the state our data. \n\n• Analyse and produce data coverage and quality statistics across internal and external data sets to provide a high level of awareness across multiple teams. \n\n• Following agile software development practices such as test-driven development, continuous delivery and pair programming. \n\n• Sharing responsibility for all operational aspects of the software that we build, in support of our “you build it; you run it” philosophy where dev-ops is a part of everyday life. \n\n• Learning –we are constantly learning together, mentoring each other and striving to do things better \n\nWho we’re looking for\nOur ideal candidate will have a mix of skills in the areas below. Don’t hesitate to apply even if you don’t tick every item: \n\n• Programming skills in languages such as SQL, Python, R, C#, or similar. While we’re happy for you to learn specific languages on the job, you must have the ability to code. \n\n• A passion for: Machine Learning, Deep Learning / Generative AI, Time Series Analysis & Forecasting, Software Development \n\n• In-depth knowledge of the machine learning model lifecycle. \n\n• Experience with key ML and hosting libraries, such as XGBoost, LightGBM, Scikit-learn, PyTorch, Keras, HF models, Transformers, FastAPI, or Flask. \n\n• Data handling skills, including cleaning, analysing, and interpreting large data sets, and an intuitive sense for identifying when the data is incorrect or inconsistent. \n\n• Basic understanding of cloud service providers, like AWS, Azure, or Google Cloud Platform, including their core services, tools, and general applications in a business context. \n\n• Ability to communicate and collaborate effectively with business stakeholders. \n\n• Bachelors in Computer Science, Mathematics, Statistics, or a similar discipline. \n\nThe REA experience\nThe physical, mental, emotional and financial health of our people is something we’ll never stop caring about. This is a place to learn and grow.\n\nSome of our Perks & Benefits include: \n\n• A hybrid and flexible approach to working\n• Flexible leave options including, birthday leave and purchase additional leave\n• Flexible parental leave offering for primary and secondary carers\n• Our Because We Care program offers employees volunteering leave, community grants, matched payroll giving and our Community Café donates 100% of revenue to charity\n• Hackdays so you can bring your big ideas to life \n\nOur commitment to Diversity, Equity, and Inclusion \nWe are committed to providing a working environment that embraces and values diversity, equity and inclusion. We believe teams with diverse ideas and experiences are more creative, more eﬀective and fuel disruptive thinking. If you've got the skills, dedication and enthusiasm to learn but don't necessarily meet every single point on the job description, please still get in touch.\n\nJoin our Talent Neighbourhood\nKeen to be part of REA but didn't find a perfect match with this opportunity? Perhaps the timing isn't right? You should join our Talent Neighbourhood!\n\n#LI-HYBRID","source_board":"freehire:workday","source_external_id":"software-engineer-machine-learning-reagroup-f7ooxtxj","source_url":"https://reagroup.wd3.myworkdayjobs.com/reacareers/job/Sydney-NSW/Software-Engineer---Machine-Learning_R0015496","source_posted_at":"2026-08-26T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"1f8ca219-0a0e-50b1-a857-925b6e15827a","company_id":"5fa6d4dd-692a-5401-9e72-a51cf6147cc3","title":"AI Developer","location":"Perth, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Job description:\n\nAbout the Role\n\nWe are looking for a Customer Service Representative (CSR) to provide professional and reliable support to customers across different industries. The ideal candidate has experience in customer service, sales, healthcare, insurance, administration, or similar fields and is comfortable communicating with customers through phone, email, and chat.\n\nTasks\n\nKey Responsibilities\n\n• Handle customer inquiries through phone, email, chat, and other communication channels.\n\n• Provide accurate information regarding products, services, accounts, or customer concerns.\n\n• Resolve customer issues professionally and escalate complex concerns when necessary.\n\n• Assist with sales inquiries, product/service recommendations, and follow-ups.\n\n• Process customer requests, documentation, appointments, orders, or account updates.\n\n• Maintain accurate customer records and update information in CRM or internal systems.\n\n• Follow company policies, procedures, and service standards.\n\n• Coordinate with internal teams to ensure customer concerns are properly addressed.\n\n• Handle sensitive customer information with professionalism and confidentiality.\n\n• Meet established customer service, productivity, and quality targets.\n\nRequirements\n\nRequirements\n\n• At least 1 year of relevant customer service or client-facing experience preferred.\n\n• Strong verbal and written English communication skills.\n\n• Professional, patient, and customer-focused approach.\n\n• Good problem-solving and decision-making skills.\n\n• Ability to handle multiple tasks and work in a fast-paced environment.\n\n• Comfortable using CRM systems, Microsoft Office/Google Workspace, and other business software.\n\n• Good attention to detail and documentation skills.\n\n• Able to work independently while being a strong team player.\n\n• Willingness to learn new systems, products, and processes.\n\nNice to Have\n\n• Experience supporting US, Australian, or international clients.\n\n• Experience with CRM, ticketing, phone, or healthcare/insurance platforms.\n\n• Sales or upselling experience.\n\n• Experience working remotely or with international teams.\n\nWhat We’re Looking For\n\nWe’re looking for someone who is customer-focused, adaptable, reliable, and professional, with the ability to quickly learn new products, systems, and processes.\n\nBenefits\n\nNA\n\nCandidates with experience in any of the following are encouraged to apply:\n\n• Customer Service / Call Center\n\n• Sales / Business Development\n\n• Healthcare / Medical Support\n\n• Insurance / Claims / Policy Support\n\n• Banking / Financial Services\n\n• Administrative Support\n\n• E-commerce / Retail\n\n• Technical Support\n\n• Travel and Hospitality","source_board":"freehire:join","source_external_id":"ai-developer-workmatepro-wntxfzyf","source_url":"https://join.com/companies/workmateprocom/16713985-ai-developer","source_posted_at":"2026-08-19T03:45:04Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"2e1b2156-5db8-5acf-a62e-ce8e442fe071","company_id":"607feb4f-5403-5f3f-ad4a-f35a9346827a","title":"AI engineer","location":"Keysborough, Melbourne VIC","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Salary: $130,000 – $160,000 per year\nKUGA ENERGY | CAREERS\nAI Integration Engineer\nClaude & ChatGPT · Custom CRM · Keysborough, VIC · Full time\n\nAustralia runs on energy that is getting cleaner, cheaper and a lot more complicated to sell, install and service. Kuga Energy is at the front of that shift — designing, installing and managing commercial solar, battery storage, EV charging and energy efficiency projects for businesses right across the country, from shopping centres and cold storage to aged care and manufacturing.\nWe have built our own CRM to run that business end to end: leads, site assessments, proposals, system design inputs, installation scheduling, compliance paperwork and post-install service. It is genuinely ours, and it holds a decade of hard-won operational knowledge. Now we want to put large language models to work inside it.\nThis is a new role and a hands-on one. You will be the person who takes Claude and ChatGPT from interesting demos to production features our sales, design and operations teams use every single day.\nPosition\nAI Integration Engineer (Claude & ChatGPT)\nLocation\nKeysborough, VIC 3173 — in office\nEmployment type\nFull time, permanent\nReports to\nHead of Technology / Operations\nSalary\nCompetitive base + superannuation, commensurate with experience\n\nWhat you will actually be doing\n• Design and build LLM-powered features inside our custom CRM using the Anthropic (Claude) and OpenAI (ChatGPT) APIs — not bolt-on chatbots, but capabilities wired into real workflows.\n• Automate the paperwork that slows us down: drafting and quality-checking commercial proposals, summarising site assessments, extracting data from electricity bills and interval data, pre-filling grid connection and rebate documentation, and turning long email threads into clean CRM records.\n• Build retrieval over our own knowledge — product specs, install standards, compliance requirements, historical projects — so the models answer from Kuga’s data rather than guessing.\n• Choose the right model for the right job. You will benchmark Claude and ChatGPT (and whatever comes next) on our actual tasks and make evidence-based calls on cost, latency and accuracy.\n• Own the plumbing: API integration, prompt and context design, structured outputs, tool/function calling, evaluation harnesses, monitoring, token cost management and graceful failure handling.\n• Put guardrails around it. Customer and site data is sensitive; you will make sure our use of third-party models is secure, auditable, privacy-compliant and appropriately human-supervised.\n• Work shoulder to shoulder with sales, engineering, project delivery and service teams to find the highest-value problems — then ship, measure and iterate.\n• Bring the rest of the business along: internal documentation, training and sensible policy on what AI should and should not be trusted with.\nWhat we are looking for\nEssential:\n• Demonstrable production experience building with LLM APIs — Anthropic Claude, OpenAI, or both. We care far more about what you have shipped than where you learned it.\n• Strong software engineering fundamentals in Python, JavaScript/TypeScript, PHP or similar, and genuine comfort integrating with an existing custom application and its database.\n• Solid grasp of REST APIs, webhooks, authentication, queueing and asynchronous processing.\n• Practical experience with retrieval-augmented generation, embeddings and vector search.\n• Prompt engineering and evaluation skills — you can tell the difference between a prompt that demos well and one that holds up across a thousand real records.\n• Sound judgement about data security, privacy and Australian Privacy Principles when sending business data to third-party model providers.\n• Clear communication with non-technical colleagues, and the initiative to run with a problem in a role that has no established playbook.\n• Full working rights in Australia and the ability to work from our Keysborough office.\nHighly regarded:\n• Experience in energy, solar, construction, field services or another operations-heavy industry.\n• Background in CRM or ERP integration work.\n• Agent frameworks, workflow orchestration or MCP-style tool integrations.\n• Document parsing and OCR at scale (proposals, invoices, technical datasheets, meter data).\n• Cloud infrastructure (AWS, Azure or GCP), CI/CD and observability tooling.\n• Data analysis and reporting skills that let you prove the value of what you built.\nWhy Kuga\n• Real impact on decarbonisation. You will not be optimising ad clicks. Every project we deliver takes commercial and industrial load off fossil generation.\n• A blank page. This is our first dedicated AI role. You will set the direction, the stack and the standards rather than inherit someone else’s.\n• Our own platform. Because the CRM is built in-house, you can change it. No vendor roadmap, no waiting on a third party to expose an endpoint.\n• A business with runway. An established, award-winning commercial solar company with offices in Victoria, New South Wales, Queensland and the Philippines.\n• Support to keep sharpening. Budget for training, conferences and the model access you need to do the job properly.","source_board":"freehire:seek","source_external_id":"ai-engineer-kuga-electrical-7qaco4oe","source_url":"https://www.seek.com.au/job/94024875","source_posted_at":"2026-08-17T11:24:28Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"10e9ebe0-2c8d-5acd-bfdc-a13c3666ea33","company_id":"4a80f2b2-5593-550f-89f2-dfcf7dd96a61","title":"Azure AI Engineer","location":"Sydney NSW","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Please Note, for this project you will need to be based in in Australian (East Coast), with either Australian Permanent Residency, or Australian Citizenship. The client cannot sponsor.\n\nNuage has partnered with an enterprise client, investing heavily in AI capability across internal platforms, and we’re looking for Senior hands on engineers to join a specialist team delivering and improving production grade Copilot solutions.\n\nAbout the role:\nThis is a remote role open across Australia’s East Coast, sitting within a small team of technical SMEs focused on building, troubleshooting, and improving AI driven workflows running on top of Microsoft’s modern AI stack. The work is practical and delivery focused. You’ll be implementing new functionality, improving agent behaviour, debugging issues in production, and helping ensure released solutions perform reliably in live enterprise environments.\n\nAbout you:\n\n• Strong hands-on experience working with Microsoft Copilot / Copilot Studio / Azure OpenAI / Azure AI Foundry \n• In-depth Azure build experience across (Azure functions, Synapse, Fabrick and Bicep) \n• Practical experience writing and analysing KQL queries \n• Experience working with GitHub Copilot or similar AI-assisted development tools This role will suit someone who enjoys practical engineering, likes understanding why systems fail, and wants to work on modern enterprise AI delivery without heavy stakeholder ownership.\n\nIf you enjoy building, fixing, and improving real AI systems in production, this is a strong opportunity to work inside a growing enterprise AI environment. We have multiple roles on offer for strong engineers based across the east coast of Australia.","source_board":"freehire:seek","source_external_id":"azure-ai-engineer-nuage-technology-group-73hcg7ej","source_url":"https://www.seek.com.au/job/93955617","source_posted_at":"2026-08-13T06:27:19Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"4abde6cd-ce6e-5fab-afe2-7cde6bb9ad16","company_id":"25f11f39-260e-5c9a-89c1-e20887e049d0","title":"AI Engineer","location":"Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"The role\nThe Artificial Intelligence (AI) Engineer is responsible for assisting in the design and development of scalable AI solutions to solve our business problems. The role will focus on building and operationalising AI solutions that drive innovation and deliver practical business value. \nThe AI Engineer will work closely with solutions architects, software engineers, and product teams to develop AI-enabled products, testing and tuning models, and ensuring solutions are secure, reliable, and scalable.\n\nThe team\n\nAPRA’s Technology team delivers, maintains, and enhances essential information technology services that support the organisation's productivity, strategic objectives, and business unit priorities.\nTechnology partners with stakeholders to design, implement and maintain IT solutions that meet the needs of the organisation and ensuring these are secure and aligned with APRA’s technology architecture.\n\nKey responsibilities\n\n• Support the testing, and deployment of new AI systems and enhancements to existing architectures\n• Ensure that AI products and solutions are robust, efficient, and easy to maintain.\n• Develop prototypes and proof of concepts to explore new AI capabilities.\n• Collaborate with cross-functional teams to identify business needs and turn them into integrated AI solutions.\n• Evaluate, fine-tune and optimise AI models for performance, scalability, and ethical outcomes.\n• Apply techniques such as prompt engineering, RAG, and model evaluation frameworks.\n• Monitor and improve AI systems ensuring reliability and user trust.\n• Optimise models to ensure performance and efficiency.\n• Stay up to date with the latest AI trends, tools and technologies to contribute to discussions and innovation within the team.\n• Contribute to best practices, documentation and knowledge sharing to support scalable and sustainable delivery.\n\nAbout you\n\n• Proven experience working with AI platforms (particularly MS Copilot Studio and/or MS Foundry) and services (particularly Azure DevOps.)\n• Practical knowledge of generative AI, LLMs, and machine learning frameworks (e.g. PyTorch, Tensorflow, MLFlow, RAG models, Langchain, etc.).\n• Proficiency in coding languages such as Python, with experience in libraries such as Pandas, NumPy, and Scikit-learn.\n• Experience with prompt engineering and fine-tuning large language models (LLMs)\n• Familiarity with neural networks, predictive modelling, and natural language processing\n• Familiarity with Agile delivery methodologies and SecDevOps practices.\n• Ability to quickly prototype and iterate solutions using modern tools, including low-code platforms where appropriate.\n• Passion for problem-solving, curiosity to explore new technologies, and a passion for continuous learning to keep up with the fast-changing AI field.\n• Excellent communication and collaboration skills, with the ability to engage both technical and non-technical stakeholders.\n• AI certifications from a recognized provider is a bonus.\n\nTo work with us, you need to be an Australian citizen with eligibility to obtain and maintain Australian Government Security clearance.\n\nAbout APRA\nThe Australian Prudential Regulation Authority (APRA) places you at the heart of Australia’s financial services industry. APRA serves the Australian community by helping ensure financial institutions deliver on the financial commitments they make, within a stable, efficient and competitive financial system. \n\nAt APRA we’re committed to providing an inclusive workplace where everyone belongs, feels valued and respected. We aspire to attract and foster diversity of background, thought, and experience, recognising that a broad range of perspectives, approaches and ideas makes us stronger, and better enables us to meet our obligation to protect the financial wellbeing of the Australian community. When applying, please inform us of any adjustments you may need during the interview process.","source_board":"freehire:oracle","source_external_id":"ai-engineer-australian-prudential-regulation-authority-aehpktom","source_url":"https://ejkm.fa.ap1.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/45","source_posted_at":"2026-08-13T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"a2e62d17-61da-53fa-86d5-ad62f6c49ad3","company_id":"9246b960-088f-55b9-8a30-fe3f964e13be","title":"AI Engineer","location":"Sydney, NSW, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"How will I help?\n\nIf you’re a hands-on AI Engineer who loves building, shipping, and scaling real AI products — this is your moment. You’ll work in delivery squads designing, building, and operationalising production-grade AI and GenAI solutions that directly enhance Westpac’s products and services. \n\nIt’s an exciting time for AI at Westpac, and you’ll be part of our rapidly growing DDAI (Data, Digital & Artificial Intelligence) team — where ideas move fast and models go live.\n\nThis role is for engineers who want to build, deploy, and own AI in production, working side-by-side with data scientists, software engineers, and product managers. To hit the ground running, you will have real-time experience in the AI Engineering space and can demonstrate solid hands-on AI experience beyond experimentation and POCs. \n\nYour responsibilities include:\n\n• Designing, building, and deploying machine learning models and GenAI applications that solve genuine business problems.\n\n• Working hands-on with large-scale data, from preprocessing through to insights and features.\n\n• Building robust data pipelines and APIs (batch, real-time and streaming).\n\n• Implementing GenAI solutions using modern frameworks, prompting techniques, RAG patterns, fine-tuning, and evaluation.\n\n• Deploying models into production and monitoring performance in the real world.\n\n• Collaborating across squads to embed AI into products and services.\n\n• Keeping pace with fast-moving advances in GenAI, ML and big data — and applying them where they matter. \n\n• Writing clear documentation to support reproducibility, learning and scale. \n\n• Troubleshooting model, data, and deployment issues end-to-end. \n\nKey ingredients for success … \n\n• A tertiary qualification in Computer Science, Engineering, Mathematics, or a related field.\n\n• Hands-on production AI/ML experience including working knowledge of MLOps and AI tooling, \n\n• Strong Python skills and deep experience with TensorFlow, PyTorch or scikit-learn.\n\n• Demonstrable GenAI/LLM build experience (prompting, agents, RAG, fine-tuning) using frameworks such as LlamaIndex, LangChain, AutoGen, DSPy. \n\n• Cloud platform expertise and containerisation (Docker, Kubernetes)\n\n• Strong software engineering fundamentals — Git, CI/CD, clean code. \n\n• Experience with big data technologies (Spark, Hadoop or similar), plus experimentation and A/B testing. \n\n• A problem-solving mindset, great people skills and a passion for building AI in general.\n\nWhy join us?\n\nWe’re obsessed with becoming our customers’ #1 banking partner for life — and we’re building the AI capability to make that real.\n\nAt Westpac, you’ll find:\n\n• Exclusive banking benefits, including employee-only mortgage rates.\n\n• Flexible work and additional leave options (Culture, Lifestyle and Wellbeing leave)\n\n• Tailored learning and development to help you grow your AI career.\n\n• Plenty of opportunities to give back through community and volunteering initiatives.\n\nDoes this sound like you? \n\nTo apply, select Apply or Apply NOW and submit your CV and cover letter.\n\nWe are committed to creating a supportive and inclusive workplace. We welcome applicants of all ages, genders, backgrounds, and abilities, and provide additional support for veterans, Indigenous Australians, and the neurodiverse community.\n\nIf you require adjustments during the recruitment process, you can find further information and contact details by visiting the “People with Disability and/or needing Accessibility Requirements” page on our website.","source_board":"freehire:oracle","source_external_id":"ai-engineer-westpac-2luwwy2n","source_url":"https://ebuu.fa.ap1.oraclecloud.com/hcmUI/CandidateExperience/en/sites/jobsearch/job/65610","source_posted_at":"2026-08-12T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"fc5c4686-a59e-50e7-8a7a-d9f3cd6876c9","company_id":"fa657fb1-d23a-5f33-8d8f-f8511af7af81","title":"AI Engineer","location":"North Sydney, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"The Role\n\nThis is a software engineering role first and foremost. You'll build and ship product capabilities across our platform — and a meaningful part of your work will be AI-powered features, which is why we're looking for an experienced software engineer who also brings real AI engineering experience: someone who has built and shipped LLM-powered product capabilities to production, in front of real end users and customers.\nDay to day, you'll work across the full breadth of our product. Some of what you build will be conventional product engineering — features, integrations, and improvements to core workflows. Some of it will be AI-driven capabilities that help AEC professionals work faster and smarter. In both cases, you'll own your work end to end: from shaping what to build with product, through architecture and implementation, to production monitoring and iteration.\nYou'll join a product engineering organisation that takes AI seriously across the whole software lifecycle, and you'll help set the standard for how we build AI capabilities well: reliably, safely, and with genuine customer value.\n\nResponsibilities \n\n• Design, build, and ship product features across our platform — both conventional product capabilities and AI-powered ones — for customers across Australia, the UK, and the US.\n\n• Write production-quality application code across our stack, contributing to core product workflows, integrations, and platform improvements.\n• Build LLM-powered product capabilities and the engineering around them: prompt and context management, retrieval, tool/function calling, orchestration, guardrails, and fallback behaviour.\n• Establish evaluation and observability practices so we know our AI features work — quality metrics, regression testing, monitoring of cost, latency, and output quality in production.\n• Work with product managers and designers to shape features that solve real customer problems and be honest about where AI is (and isn't) the right tool for the job.\n• Share what you learn: raise the AI engineering capability of the broader engineering team through patterns, code review, and mentoring.\n\nQualifications / Experience \nMust have: \n\n• Strong software engineering foundation with several years of experience building and shipping production web applications. \n\n• Experience with some of our tech stack — .NET/C# on the backend; Angular and/or React on the front end. We don't expect deep experience across all of it, but we do need meaningful overlap, ideally on the backend (.NET/C#) in particular. \n• Demonstrated experience building and shipping AI/LLM product capabilities to production with real end users — not just prototypes, demos, or internal experiments. \n• Hands-on experience with LLM APIs and patterns: prompt engineering, structured outputs, RAG/retrieval, tool use/function calling, and agentic workflows. \n• Familiarity with cloud AI services and model providers (e.g., Azure Foundry, Anthropic, OpenAI, AWS Bedrock). \n• Experience with vector databases, embeddings, and semantic search. \n• Exposure to AI-assisted development tooling and agentic engineering workflows. \n• Experience with evaluation and quality practices for non-deterministic systems — you know how to measure whether an AI feature works. \n• Pragmatic product judgment: you can weigh cost, latency, accuracy, and user experience trade-offs and make sensible calls. \n• Strong communication skills — you can explain AI system behaviour and trade-offs to product, leadership, and non-AI engineers. \nNice to have: \n\n• Experience in B2B SaaS, ideally multi-tenant products. \n• Experience with agent frameworks (e.g. LangGraph, Microsoft Agent Framework, CrewAI, etc.) \n• Domain exposure to AEC, professional services, or project-based businesses. \n\nLocation & Work Setup \nOur preference is for this role to be based in Sydney, Australia, working in a hybrid arrangement with our local team. That said, we're remote-friendly and open to strong candidates working from anywhere in Australia or New Zealand. \nThe extra bits \n\n• Annual work'versary day off \n• $1000 WFH allowance \n• Hybrid work (Sydney-based) / remote-friendly across Australia & New Zealand \n• New tech to work your very best + company swag \n\nTotal Synergy is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees.","source_board":"freehire:rippling","source_external_id":"ai-engineer-total-synergy-hscbctea","source_url":"https://ats.rippling.com/totalsynergycareers/jobs/63cac952-20df-4365-9a94-806172eac666","source_posted_at":"2026-08-10T03:50:09Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"f3663b41-5601-5908-9d01-1a681e2866b3","company_id":"df69ea17-9781-533f-8901-922bd034c22c","title":"Forward Deployed AI Engineer","location":"North Sydney, New South Wales, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Are you passionate about building and deploying production-grade AI systems that solve real-world business problems?\nDo you enjoy working directly with customers, turning complex challenges into scalable agentic AI solutions with measurable impact?\nReady to lead hands-on AI delivery in customer environments while shaping technical direction and driving innovation at scale?\n\nAs our new Senior Forward Deployed AI Engineer, you will lead the delivery of production-grade agentic AI solutions for customers across Australia, working hands-on from problem discovery through deployment and iteration. In this customer-facing role, you will design, build, and deploy scalable AI systems in real-world environments, helping organisations solve complex business challenges and achieve measurable outcomes through innovative AI solutions.\nKey Responsibilities\n\n• Lead customer engagements from problem discovery to deployed AI solutions, acting as the senior technical counterpart \n• Translate complex business challenges into pragmatic, agentic AI systems (e.g. tool-using, multi-step AI workflows interacting with external systems) operating over text, speech, and/or video data, depending on customer use case\n• Design, build, and deploy production-grade AI systems in real customer environments \n• Develop and maintain high-quality production code, integrating models and agents into customer platforms (cloud or on‑premises) \n• Architect, build, and operate end-to-end AI systems, including monitoring and iteration in production \n• Design and operate agent-based systems, including orchestration, tool use, and interaction with external systems \n• Validate and communicate both technical performance and business value to customer stakeholders \n• Turn prototypes into robust, scalable solutions, balancing speed, quality, and maintainability \n• Set technical direction on projects and act as a role model for engineering and AI best practices\n• Mentor and support less experienced engineers, raising the overall delivery standard","source_board":"freehire:powertofly","source_external_id":"forward-deployed-ai-engineer-softwareone-gvee6n23","source_url":"https://powertofly.com/jobs/detail/2545458","source_posted_at":"2026-08-06T11:43:04Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"ab15a7b7-3573-57ab-ae22-5a2660bb6a4c","company_id":"f7213a22-4ad6-54b5-9428-78c721bf3394","title":"GCP AI Engineer","location":"Sydney, NSW, au","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"We are seeking a highly skilled GCP AI Engineer with experience to join a leading-edge Intelligent Contact team. This is a critical hire focused on advancing our AI development capabilities and building the next generation of intelligent, automated customer interactions.\nIn this role, you will move beyond basic, scripted automation to develop high-reasoning, context-aware agents that provide seamless service at an enterprise scale. You won't just be building chatbots; you will be architecting autonomous AI systems capable of understanding intent, managing complex dialogue states, and retrieving real-time information to solve customer problems proactively.\nKey Responsibilities\n\n• Autonomous Agent Architecture: Design, develop, and orchestrate high-reasoning, context-aware conversational agents utilizing Google Cloud’s advanced AI ecosystem (including Vertex AI and foundational Gemini models).\n• Advanced RAG & Knowledge Retrieval: Blueprint and optimize production-ready Retrieval-Augmented Generation (RAG) architectures and integrate Knowledge Graphs to drive sophisticated, hallucination-free AI reasoning.\n• Complex Dialogue Management: Engineering fluid dialogue state systems capable of handling non-linear, multi-turn user journeys without falling back on rigid, scripted decision trees.\n• Real-Time Data Integration: Implement function calling and dynamic tool-use pipelines, enabling AI systems to interact securely with enterprise APIs and retrieve real-time data to solve customer inquiries proactively.\n• Enterprise Scaling & MLOps: Productionize, monitor, and scale machine learning and LLM workflows within GCP Vertex AI, ensuring high availability, low latency, and robust guardrails.\n• Technical Leadership: Guide critical architectural decisions, navigate complex enterprise integration challenges, and mentor junior or mid-level team members within the conversational AI space.\nTo be successful in this role, you will bring a deep technical background in machine learning and a passion for production-ready AI. We are looking for:\n\n• \nCloud Expertise: Hands-on experience with Google Cloud Platform (GCP) is essential. You should be proficient in leveraging services such as GCP Vertex AI to build and scale models.\n• \nProven AI Delivery: Demonstrable experience in building and successfully deploying Intelligent Agents in a commercial or enterprise environment.\n• \nTechnical Depth: Deep expertise in RAG architectures and/or the implementation of Knowledge Graphs to drive sophisticated AI reasoning.\n• \nSenior Engineering Mindset: Ability to guide architectural decisions, solve complex integration challenges, and mentor within the AI space.\n\nWhy join us: \nNCS Australia is where you can feel at home, nurturing your talents and skills as we make tomorrow together, one day at a time. Our benefits include paid parental leave, initiatives focused on your well-being and discounted health insurance. You will also enjoy discounts on various products and services and be regularly recognised and rewarded for high performance. We are committed to your career development through our Capability Fingerprint, industry and partner training programs, special interest groups, and an AI-driven learning platform. No matter where you are in your career, we offer meaningful work and opportunities for growth.\n\nNCS Australia is an equal-opportunity employer, and we take pride in our commitment to valuing and supporting our people and the communities we serve.We are dedicated to attracting, retaining and developing our people regardless of gender identity, ethnicity, sexual orientation, disability and age. Applications are encouraged from all sectors of the community and we strongly encourage applications from the Veterans, Aboriginal and/or Torres Strait Islander community.\nAt NCS Australia, we are committed to supporting adjustments throughout the recruitment and selection process, as well as during employment. We actively support and encourage people with disability to apply. \n\nAgencies:\nWe’ve got this. We request that you do not contact NCS employees outside of the Talent Acquisition team. NCS exclusively accepts resumes from agencies on our preferred supplier panel through the NCS Agency Portal. Agencies that submit resumes must have a valid fee agreement and be assigned to the particular requisition by the Talent Acquisition team. Any resumes that are submitted outside of this process will become the sole property of NCS. If a candidate is hired outside of this process, no fee or payment will be given.\n\nWork rights and background checks: \nTo be eligible for a position with us, applicants will need to have valid work rights for Australia and be willing to undergo a comprehensive background checking process, including probity and police checks","source_board":"freehire:smartrecruiters","source_external_id":"gcp-ai-engineer-ncsaustralia-ulsp3lid","source_url":"https://jobs.smartrecruiters.com/NCSAustralia/6000000001170690-gcp-ai-engineer","source_posted_at":"2026-06-22T03:24:55Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"ac34d3cc-cd47-541e-bebc-f58404bd52ad","company_id":"7f01713e-311c-531f-a93c-1be0de8853c3","title":"ML Engineer","location":"South Melbourne, Victoria","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Kogan.com is a pioneer of Australian eCommerce, and the software we build is used by millions of customers every day. You'll join a fast-moving engineering team with real ownership, shipping to production daily and using AI as part of how we work.\n\nAs a Data Engineer you'll design and run the data and ML pipelines that let teams across Marketing, Purchasing, Logistics and Finance make confident, data-driven decisions.\nWhat you'll do:\n\n• Machine Learning Development: Design, build and deploy machine learning models that solve practical business problems, including recommendation systems, demand forecasting, customer segmentation, churn prediction, pricing optimisation and fraud detection.\n\n• Production ML Systems: Build reliable and scalable machine learning services that deliver predictions in both real time and batch environments, ensuring strong performance, reliability and cost efficiency.\n\n• MLOps & Automation: Develop and maintain MLOps pipelines that automate model training, validation, deployment, monitoring and retraining.\n\n• Feature Engineering: Work with large datasets to create robust feature pipelines and reusable datasets that improve model performance and accelerate experimentation.\n\n• LLM & Generative AI Applications: Design, evaluate and deploy AI powered solutions using large language models (LLMs), retrieval systems, agents and emerging AI technologies to enhance customer experiences and internal productivity.\n\n• Model Monitoring & Optimisation: Implement monitoring frameworks to track model performance, drift, accuracy and business impact, continuously improving models in production.\n\n• Cross Functional Collaboration: Partner with Product Managers, Engineers, Analysts and business stakeholders to identify opportunities where machine learning can create measurable value.\n\n• Software Engineering Excellence: Develop solutions in line with software engineering best practices, including Git, CI/CD, trunk based development, testing and observability.\n\n• AI Collaboration: Contribute to experiments with AI and emerging technologies, helping shape how Kogan.com leverages machine learning and automation across the business.\n\nWhat you'll need:\n\n• Strong Python Skills: Commercial experience building machine learning applications and data pipelines using Python and relevant machine learning libraries.\n\n• Machine Learning Expertise: Hands on experience developing, evaluating and deploying machine learning models in production environments.\n\n• MLOps Experience: Experience building and maintaining model deployment, monitoring and retraining pipelines using modern MLOps practices and tools.\n\n• Data Engineering Foundations: Strong SQL skills and experience working with large datasets, feature engineering workflows and distributed data processing systems.\n\n• Cloud Experience: Hands on experience with cloud platforms, preferably Google Cloud Platform (GCP), including Vertex AI, BigQuery and Cloud Run.\n\n• Software Engineering Best Practices: Strong understanding of Git, CI/CD, testing frameworks, containerisation and production system reliability.\n\n• AI & LLM Experience: Experience working with LLMs, embeddings, vector databases, RAG architectures or AI agents through commercial or personal projects.\n\n• Problem Solving Mindset: A practical engineering approach that balances experimentation and innovation with reliability, scalability and business impact.\n\nBonus Points\n\n• Recommendation & Forecasting Systems: Experience building recommendation systems, search ranking models or forecasting solutions.\n\n• ML Platforms & Tooling: Exposure to ML platforms and tools such as Vertex AI, Databricks, SageMaker or Kubeflow.\n\n• Streaming & Event Driven Systems: Experience with event driven architectures and streaming technologies such as Kafka or Pub/Sub.\n\n• LLM Application Deployment: Experience deploying AI applications powered by LLMs and agent frameworks.\n\nWhy Kogan.com?\n\n• AI-Native Engineering: AI is deeply embedded in how our Engineering teams build and operate. We’re moving beyond standalone LLM use into agentic workflows, AI-assisted development and automation integrated into real engineering systems and processes. Engineers have access to leading AI tools, hands-on training and the freedom to experiment with new ways of designing, building and shipping software.\n\n• Our culture is unlike anywhere else and regardless of where you are in your career journey, we empower you to do your best work and have a big impact. Check us out & .\n\n• Work with an incredible team to solve important challenges, helping to drive Australia and New Zealand's eCommerce future.\n\n• Your role has a lot of ownership, autonomy and little red tape. You'll be empowered to achieve positive outcomes and your work will have a real impact.\n\n• You'll be at the forefront of the eCommerce industry and be part of a company that are the Pioneers of eCommerce in Australia.\n\n• Be an Intrepreneur, playing a hands on role in shaping our strategy at our HQ.\n\n• Learning budget of $1000.\n\n• A range of employee benefits such as; complimentary Kogan First Membership, team exclusive discounts, Health & Wellness program, Learning & Development and Lunch & Learns, Hackathons, Team member referral program, Company and team events and celebrations, community engagement (volunteering) and extensive career development opportunities plus loads more!\n\nTo find out more about how we work, our tech stack, processes and company culture, visit and","source_board":"freehire:lever","source_external_id":"ml-engineer-kogan-rrjzxtl3","source_url":"https://jobs.lever.co/kogan/5dc7a8ea-a5c0-48e1-bfae-273bba001c87","source_posted_at":"2026-06-22T01:51:12Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"c4a9c34c-061d-56a5-9cc9-27bb92f63477","company_id":"f426cf75-1ef7-567a-a4e2-e69a4d916f54","title":"AI Software Engineer (Back End)","location":"Melbourne","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About the role\nMaincode is training Matilda, a large language model built and trained from scratch in Australia. Our new compute cluster is now live, and we are scaling the next version and deploying it publicly.\nThis role sits inside the production system that serves Matilda. You will build and maintain the back end services that make the model usable in the real world: APIs, infrastructure, and the systems that turn a trained model into a reliable public capability.\nWe build AI systems end to end. We design the architectures, run the infrastructure, train the models, and operate the systems ourselves. Matilda is not a research prototype. It is a production system trained at scale and served publicly.\nMaincode operates one of the largest private AI compute environments in Australia, built for training and operating our own models. You will be working directly on the systems that deploy and serve a model trained from scratch.\n\nWhat you would actually do\nYou will build and maintain the services that sit between the model and the outside world.\nThis includes work such as:\n\n• \nBuilding and maintaining services that handle model inference and user requests\n• \nDesigning systems that manage requests, sessions, and streaming responses\n• \nImplementing reliability mechanisms such as rate limiting, retries, and graceful failure\n• \nBuilding authentication and access controls for public usage\n• \nDesigning systems for logging, telemetry, and evaluation signals\n• \nImproving latency, throughput, and reliability of model serving\n• \nIntegrating new model checkpoints into the production system\n• \nWorking closely with training and infrastructure engineers to deploy and operate the model\nMuch of the work happens inside production systems: logs, traces, performance profiles, and deployment pipelines. The goal is not polish. The goal is a system that stays up, stays fast, and behaves predictably under load.\n\nThe kind of person who does well here\nWe are looking for engineers early in their careers who want to learn how production AI systems are actually built and operated.\nYou may have one or two years of experience building production software. What matters most is curiosity, reliability, and the willingness to learn how large scale systems behave under real constraints.\nPeople who tend to do well here:\n\n• \nCare about runtime behaviour and system reliability\n• \nEnjoy debugging real systems rather than writing theoretical code\n• \nThink clearly about system boundaries and failure modes\n• \nStay calm and methodical when production behaves unexpectedly\n• \nWant to understand how large scale AI systems actually work\nYou do not need prior experience serving large language models. You do need the discipline to build systems that are hard to break.\n\nHow you would work\nYou will use code as a way of shaping a production system.\nYou should be comfortable:\n\n• \nBuilding back end services in a modern language (Python is common here)\n• \nWorking with APIs and service interfaces\n• \nDesigning systems that remain stable under load\n• \nReading logs and system metrics to understand behaviour\n• \nCollaborating closely with training, infrastructure, and product engineers\nSpeed matters, but so does rigour. Reliability is a feature.\n\nWhat this role is not\n\n• \nIt is not maintaining internal business software or conventional product back ends\n• \nIt is not integrating third party AI services or building on top of external models\n• \nIt is not primarily front end work or prompt engineering\n• \nIt is not incremental feature work on mature systems\nThis role focuses on building and operating the systems that deploy and run a model we train ourselves, where the core problems are performance, scale, and reliability.\n\nWhy Maincode\nMaincode builds AI systems end to end. We train the models, run the infrastructure, and operate the systems ourselves.\nYou will work with a small team that:\n\n• \nBuilds the full AI stack rather than outsourcing it\n• \nTreats reliability and system design as core engineering problems\n• \nValues engineers who want to understand how systems actually work\n• \nIs building long term capability in training, deployment, and serving\nIf you want to work directly on the systems that deploy and operate a large language model trained from scratch, this role will put you inside that work.\n\nNote\nThis is a full time role based in Melbourne, working closely with our in person engineering and research team. At this time we are not able to offer visa sponsorship, so applicants must have existing and unrestricted work rights in Australia.","source_board":"freehire:ashby","source_external_id":"ai-software-engineer-back-end-maincode-733z5sbu","source_url":"https://jobs.ashbyhq.com/maincode/a2251b3b-d130-4dec-af6d-5a8d6ff63c91","source_posted_at":"2026-03-09T00:52:34Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"a97b87c4-fd28-585c-aed4-f23113bc3be1","company_id":"f426cf75-1ef7-567a-a4e2-e69a4d916f54","title":"AI Software Engineer (Front End)","location":"Melbourne","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About the role\nMaincode is training the next version of Matilda, the first large language model built and trained from scratch in Australia. We are now scaling the model and deploying it as a live production system.\n\nTo do that, we build AI systems from first principles. We design the architectures, run the infrastructure, shape the training process, and operate the systems that serve our models.\n\nMatilda is a production system, not a research prototype, built to be deployed and served for open public access. If the training stack is how Matilda learns, the product is how people experience it. This role sits directly in that delivery layer.\n\nYou will build the front end systems that make Matilda usable, fast, and trustworthy for real users. You will work on the interfaces that turn a model into a product: streaming responses, conversation state, safety UX, performance, reliability, and the tooling that helps the team iterate quickly.\n\nWhat you would actually do\nYou will build and maintain the front end systems that power Matilda’s public product and internal tools.This includes:\n\n• \nBuilding the core web interface for interacting with Matilda (chat, sessions, history, settings)\n• \nImplementing fast, reliable streaming UX for model outputs (real-time tokens, partial results, cancellation, retries)\n• \nDesigning and building UI workflows that support safe and responsible use (reporting, refusals, user feedback, content handling)\n• \nWorking closely with backend and infra engineers to integrate APIs, auth, rate limits, and observability\n• \nImproving performance across the app (latency, bundle size, rendering, perceived responsiveness)\n• \nBuilding internal dashboards and tools that help the team operate the system (usage, quality signals, feedback triage)\n• \nDebugging issues across browsers, devices, networks, and production environments\n• \nRaising the bar on quality through testing, monitoring, and careful rollout practices\nYou will spend time in code, UI state, performance traces, and production metrics.\n\nThe kind of person who does well here\nWe are looking for engineers early in their careers who want to build the product surface of a frontier model, and who care about quality and reliability in real production environments. You may have one or two years of experience building production software. What matters most is curiosity, taste, and the willingness to learn how these systems behave with real users.\n\nPeople who tend to do well here:\n\n• \nCare about performance, UX quality, and edge cases that show up in production\n• \nEnjoy building clean, maintainable front end systems, not just one-off screens\n• \nHave strong debugging instincts and do not panic when something breaks\n• \nThink clearly about product tradeoffs, reliability, and failure modes\n• \nPay attention to metrics and user feedback, not just what looks good locally\n• \nWant to work close to the core system, not just build a marketing site\nYou do not need prior experience working on AI products. What matters is intellectual curiosity, persistence, and the ability to learn quickly.\n\nHow you would work\nYou will write production code that sits in the product layer of the Matilda stack. You should be comfortable:\n\n• \nWorking in TypeScript and modern front end tooling\n• \nBuilding production web applications (component architecture, state management, API integration)\n• \nImplementing real-time or streaming experiences (for example, via SSE or WebSockets)\n• \nDebugging complex UI state and issues that only occur under real conditions\n• \nCollaborating closely with user research, backend, infrastructure, and research teams\nMuch of the work sits between product and the underlying model. The model evolves quickly, but the user experience must remain stable. You will be working on the front end systems that ship Matilda to the public and help operate it day to day.\n\nWhy Maincode\nMaincode builds AI systems end to end. We prepare the data, design the training process, run the infrastructure, and operate the models ourselves. You will work with a small team that:\n\n• \nBuilds the full AI stack rather than outsourcing it\n• \nTreats product quality and reliability as part of the intelligence system itself\n• \nValues engineers who want to understand how things actually work\n• \nIs building long-term capability in training, deploying, and operating large models\nIf you want to build the product surface of a model trained from scratch, and ship it to real users, you will be close to the core work here.\n\nNote\nThis is a full time role based in Melbourne, working closely with our in person engineering and research team. At this time we are not able to offer visa sponsorship, so applicants must have existing and unrestricted work rights in Australia.","source_board":"freehire:ashby","source_external_id":"ai-software-engineer-front-end-maincode-tyoxzlug","source_url":"https://jobs.ashbyhq.com/maincode/94baa206-3a18-4386-95de-d99fd9b1e196","source_posted_at":"2026-03-05T01:51:21Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"cb795108-dd58-5eff-b811-bf939933ac4a","company_id":"f426cf75-1ef7-567a-a4e2-e69a4d916f54","title":"AI Software Engineer (Model Training)","location":"Melbourne","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"About the role\nMaincode is training Matilda, the first large language model built and trained from scratch in Australia. Our new compute cluster is live, and we are now scaling the next version.\nThis role sits directly inside that training stack. You will build the pipelines, infrastructure, and tooling that determine how efficiently Matilda trains, how stable long runs are, and how fast new experiments can be executed. Training runs last days or weeks. Small changes propagate through complex systems. The work requires precision and patience.\nWe build AI systems from first principles: designing the architectures, running the infrastructure, shaping the training process, and operating the models ourselves. Matilda is not a research prototype. It is a production system, trained at scale and served for open public access.\nMaincode operates one of the largest private AI compute environments in Australia, built for a single purpose: training our own models. This is not a role that wraps external APIs or ships user-facing features. You will be working on the systems that train a large language model from scratch.\n\nWhat you would actually do\nYou will build and maintain the systems that support large scale model training.\nThis includes:\n\n• \nDesigning and maintaining distributed training pipelines for large language models\n• \nBuilding data ingestion and preprocessing systems for large training datasets\n• \nDeveloping tooling for experiment management, checkpointing, and reproducibility\n• \nMonitoring and debugging long running training jobs across clusters\n• \nImproving reliability and observability across the training stack\n• \nOptimising training throughput across compute, memory, and data pipelines\n• \nWorking closely with researchers to translate experimental ideas into training runs\n• \nDiagnosing failures across infrastructure, training loops, and data pipelines\nTraining runs can last days or weeks. Small changes propagate through complex systems.\nYou will spend time inside code, logs, dashboards, and experiment outputs. The goal is simple: make large scale training reliable.\n\nThe kind of person who does well here\nWe are looking for engineers early in their careers who want to understand how large models are actually trained.\nYou may have one or two years of experience building production software. What matters most is curiosity and the willingness to learn how these systems behave under load.\nPeople who tend to do well here:\n\n• \nCare about how systems behave over long runtimes\n• \nEnjoy debugging complex distributed systems\n• \nPay attention to logs, metrics, and system behaviour\n• \nPrefer understanding how a system works rather than relying on abstraction\n• \nAre comfortable working close to infrastructure\n• \nHave the patience to diagnose failures that appear hours into a run\n• \nWant to learn how large scale AI training actually happens\nYou do not need prior experience training large language models. What matters is intellectual curiosity, persistence, and the ability to learn quickly.\n\nHow you would work\nYou will write production code that sits directly in the training stack.\nYou should be comfortable:\n\n• \nWorking in Python\n• \nUsing machine learning frameworks such as PyTorch or JAX\n• \nWriting reliable infrastructure for large compute workloads\n• \nDebugging distributed systems and long running jobs\n• \nCollaborating closely with researchers and infrastructure engineers\nMuch of the work sits between research and infrastructure. Ideas move quickly, but the systems that support them must remain stable.\n\nWhat this role is not\n\n• \nIt is not primarily about building user facing applications\n• \nIt is not about prompt engineering\n• \nIt is not about wrapping external APIs or third party models\nYou will be working on the systems that train our own models from scratch.\n\nWhy Maincode\nMaincode builds AI systems end to end. We prepare the data, design the training process, run the infrastructure, and operate the models ourselves.\nYou will work with a small team that:\n\n• \nBuilds the full AI stack rather than outsourcing it\n• \nTreats infrastructure as part of the intelligence system itself\n• \nValues engineers who want to understand how things actually work\n• \nIs building long term capability in training and operating large models\nIf you want to work directly on the systems that train large language models from scratch, this is the only role in Australia that will put you inside that work.\n\nNote\nThis is a full time role based in Melbourne, working closely with our in person engineering and research team. At this time we are not able to offer visa sponsorship, so applicants must have existing and unrestricted work rights in Australia.","source_board":"freehire:ashby","source_external_id":"ai-software-engineer-model-training-maincode-lujcbqag","source_url":"https://jobs.ashbyhq.com/maincode/72a94036-bd6e-4494-be1d-642fbe595810","source_posted_at":"2026-03-05T00:22:25Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"f1a56d97-49f3-5494-a10e-b75d0f80a23b","company_id":"b11a3e2a-2f70-59b2-a2d4-494c266e1870","title":"GEN AI Engineer","location":"Sydney, New South Wales, Australia","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"Infosys Consulting is the worldwide management and IT consultancy unit of the Infosys Group (NYSE: INFY), a global advisor to leading companies for strategy, process engineering, and technology-enabled transformation programs. \nWe partner with clients to design and implement customized solutions to address their complex business challenges, and to help them in a post-modern ERP world. By combining innovative and human-centric approaches with the latest technological advances, we enable organizations to reimagine their future and create sustainable and lasting business value. \nA pioneer in breaking down the barriers between strategy and execution, Infosys Consulting delivers superior business value to its clients by advising them on strategy and process optimisation as well as IT-enabled transformation. To find out how we go beyond the expected to deliver the exceptional, visit us at www.infosysconsultinginsights.com Infosys Consulting - a real consultancy for real consultants. \nRequirements\nJob Title: Generative AI Engineer\nLocation: Sydney \nEmployment Type: Full-time / Contract\nStart Date: Immediate\nAbout the Role:\nWe are seeking a highly skilled and motivated Generative AI Engineer to join our team and contribute to cutting-edge AI solutions. This role involves designing, developing, and deploying generative AI models and applications, with a strong focus on Large Language Models (LLMs), Python programming, and cloud-based infrastructure.\nYou will work closely with cross-functional teams to build intelligent systems that leverage generative AI capabilities for real-world applications.\n\nKey Responsibilities:\n\n• Design, develop, and fine-tune Generative AI models using LLMs (e.g., GPT, LLaMA, Claude, Mistral). \n• Build scalable and efficient pipelines for training and deploying GenAI models. \n• Integrate GenAI capabilities into enterprise applications and services. \n• Collaborate with data scientists, ML engineers, and product teams to define use cases and deliver AI-powered solutions. \n• Optimize model performance and ensure responsible AI practices. \n• Maintain and improve existing GenAI systems and tools. \n• Document processes, model architectures, and deployment strategies. \n\nRequired Skills & Experience:\n\n• Strong expertise in Python for AI/ML development, including libraries such as PyTorch, TensorFlow, Hugging Face Transformers, LangChain, etc. \n• Hands-on experience with Large Language Models (LLMs) and Generative AI frameworks. \n• Experience in building and deploying AI models in production environments. \n• Familiarity with prompt engineering, fine-tuning, and model evaluation techniques. \n• Understanding of NLP, deep learning, and transformer architectures. \n• Experience with REST APIs and integrating AI models into applications. \n\nPreferred / Added Advantage:\n\n• Exposure to Cloud Engineering and deployment on platforms like Azure and AWS. \n• Experience with containerization (Docker), orchestration (Kubernetes), and CI/CD pipelines. \n• Knowledge of data privacy, security, and ethical AI considerations. \n• Experience with vector databases (e.g., FAISS, Pinecone) and retrieval-augmented generation (RAG). \n\nWhat We Offer:\n\n• Opportunity to work on cutting-edge GenAI projects. \n• Collaborative and innovative work environment. \n• Flexible work arrangements. \n• Competitive compensation aligned with market standards. \nBenefits\nWe welcome applications from all members of society irrespective of age, sex, disability, sexual orientation, race, religion, or belief. We make recruiting decisions based on your experience, skills and personality. We believe that employing a diverse workforce is the right thing to do and is central to our success.\nWe offer you great opportunities within a dynamically growing consultancy. You will elaborate and deliver best practice solutions and will be able to further develop your solution design, implementation, and project to management skills. At Infosys Consulting you will discover a truly global culture, highly dedicated and motivated colleagues, a co-operative work environment and interesting training opportunities.","source_board":"freehire:workable","source_external_id":"gen-ai-engineer-infosys-singapore-australia-ibfkpd5f","source_url":"https://apply.workable.com/j/FF5C8357A0","source_posted_at":"2025-09-29T00:00:00Z","description_is_excerpt":false,"source_group":"ai_engineer"},{"id":"c1ef65eb-cd8c-5822-b8cf-db7799faa85c","company_id":"1ee0af86-eaf8-5ecf-a252-59ec6db494da","title":"Applied AI Engineer, Australia","location":"Sydney, Sydney Region","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"JD excerpt from adzuna; read the complete posting at https://www.adzuna.com.au/details/5889436399\n\nAbout Mistral Mistral provides full-stack AI solutions: from frontier models to developer tools, applications, and compute. We partner with enterprises tackling the hardest problems across high-stakes industries like finance, manufacturing, defense, healthcare, and the public sector, co-creating customized AI systems that they can run on their terms. We are a dynamic, collaborative team passionate about AI and its potential to transform society. Our diverse workforce thrives in competitive envi…","source_board":"adzuna","source_external_id":"5889436399","source_url":"https://www.adzuna.com.au/details/5889436399","source_posted_at":"2026-09-19T01:04:01Z","description_is_excerpt":true,"source_group":"ai_engineer"},{"id":"8471402e-2d62-5546-b45e-fce1f9738404","company_id":"308b5593-7b78-573f-8691-4d945824dece","title":"Software Engineer – AI","location":"The Rocks, Sydney","job_type":"full_time","industry":"AI & Software","career_id":"ml-engineer","experience_level":"not stated","description":"JD excerpt from adzuna; read the complete posting at https://www.adzuna.com.au/details/5889434861\n\nBetasha